-- =====================================================================
-- 090 — drug_profiles lote 1: 30 fármacos com mais interações
-- ---------------------------------------------------------------------
-- Perfis completos (overview público/profissional + indicações + efeitos
-- secundários + precauções) dos 30 fármacos com maior número de pares na
-- BD e sem perfil ainda. Conteúdo autorado (não copiado) a partir das
-- secções INDICATIONS AND USAGE, ADVERSE REACTIONS, CONTRAINDICATIONS e
-- WARNINGS AND PRECAUTIONS dos rótulos aprovados pela FDA (DailyMed/NIH/NLM,
-- setIDs citados por linha) e, para a diidroartemisinina+piperaquina, da
-- SmPC europeia (EMA — Eurartesim). Bullets separados por \n (renderizados
-- como lista na página). Padrão 7.6 (JOIN ON d.slug = v.slug) + ON CONFLICT
-- (drug_id) DO NOTHING — idempotente, aplicável na ordem 079 → 090.
-- =====================================================================

INSERT INTO public.drug_profiles
  (drug_id, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
   indications_pt, indications_en, side_effects_pt, side_effects_en,
   precautions_pt, precautions_en, source_pt, source_en, status)
SELECT d.id, v.overview_public_pt, v.overview_public_en, v.overview_pro_pt, v.overview_pro_en,
       v.indications_pt, v.indications_en, v.side_effects_pt, v.side_effects_en,
       v.precautions_pt, v.precautions_en, v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('rifampicina',
   'A rifampicina é um antibiótico usado principalmente no tratamento da tuberculose, sempre em associação com outros medicamentos. É muito eficaz, mas acelera a eliminação de muitos outros medicamentos, pelo que pode reduzir o efeito de tratamentos que toma em simultâneo.',
   'Rifampicin is an antibiotic used mainly to treat tuberculosis, always in combination with other medicines. It is very effective, but speeds up the elimination of many other medicines, so it can reduce the effect of treatments you take at the same time.',
   'Antibiótico rifamicina bactericida (inibidor da RNA-polimerase dependente de ADN), de largo espetro. Pedra angular do tratamento e da profilaxia da tuberculose (sempre em associação); também usado na lepra e como profilaxia de contacto. Indutor potente do CYP3A4, CYP2C9 e da glicoproteína-P — reduz a exposição de inúmeros fármacos (interações frequentemente clinicamente significativas).',
   'Bactericidal rifamycin antibiotic (DNA-dependent RNA polymerase inhibitor), broad-spectrum. Cornerstone of tuberculosis treatment and prophylaxis (always in combination); also used in leprosy and as contact prophylaxis. Potent inducer of CYP3A4, CYP2C9 and P-glycoprotein — reduces exposure of numerous drugs (interactions frequently clinically significant).',
   E'Tratamento da tuberculose pulmonar e extrapulmonar, sempre em associação com outros fármacos antituberculosos.\nTratamento da lepra (em associação).\nProfilaxia em contactos próximos de doentes com infeção meningocócica.\nTratamento de outras infeções por micobactérias (em associação, por especialista).',
   E'Treatment of pulmonary and extrapulmonary tuberculosis, always in combination with other antituberculosis drugs.\nTreatment of leprosy (in combination).\nProphylaxis for close contacts of patients with meningococcal infection.\nTreatment of other mycobacterial infections (in combination, under specialist care).',
   E'Coloração alaranjada/vermelha da urina, suor, lágrimas e lentes de contacto (esperada e inofensiva).\nNáuseas, vómitos, diarreia ou desconforto abdominal.\nErupção cutânea, comichão ou febre.\nLesão do fígado (hepatite): cansaço, icterícia, urina escura — avaliar imediatamente.\nSintomas tipo gripe, sobretudo com uso intermitente.\nProcure ajuda se tiver icterícia, hemorragias invulgares, falta de ar ou febre alta.',
   E'Orange/red discolouration of urine, sweat, tears and contact lenses (expected and harmless).\nNausea, vomiting, diarrhoea or abdominal discomfort.\nSkin rash, itching or fever.\nLiver injury (hepatitis): fatigue, jaundice, dark urine — assess immediately.\nFlu-like symptoms, especially with intermittent use.\nSeek help if you have jaundice, unusual bleeding, shortness of breath or high fever.',
   E'Tomar sempre em associação com outros antituberculosos — nunca em monoterapia.\nPode reduzir o efeito de muitos medicamentos (anticoncecionais, varfarina, muitos antibióticos) — reveja toda a medicação com o médico.\nEvitar álcool durante o tratamento (risco hepático).\nAnálises ao fígado regulares durante o tratamento.\nAvisar o médico se usa contraceção hormonal — pode falhar.',
   E'Always take in combination with other antituberculosis drugs — never as monotherapy.\nMay reduce the effect of many medicines (contraceptives, warfarin, many antibiotics) — review all medication with your doctor.\nAvoid alcohol during treatment (liver risk).\nRegular liver tests during treatment.\nTell your doctor if you use hormonal contraception — it may fail.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Rifampicina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b389b1a3-672f-47e3-916c-4a9c044b211b — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Rifampicin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b389b1a3-672f-47e3-916c-4a9c044b211b — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('claritromicina',
   'A claritromicina é um antibiótico (macrólido) usado em infeções respiratórias, da pele e em associação para eliminar a bactéria Helicobacter pylori. É eficaz, mas bloqueia a eliminação de muitos outros medicamentos, podendo aumentar os seus níveis e o risco de efeitos tóxicos.',
   'Clarithromycin is an antibiotic (macrolide) used for respiratory and skin infections and in combination to eradicate Helicobacter pylori. It is effective, but blocks the elimination of many other medicines, which can raise their levels and the risk of toxic effects.',
   'Macrólido bacteriostático (inibição da síntese proteica 50S), com atividade contra estreptococos, estafilococos, Helicobacter pylori, Legionella e micobactérias atípicas. Inibidor potente do CYP3A4 e da glicoproteína-P — aumenta os níveis de muitos fármacos (estatinas, colchicina, anticoagulantes, antiarrítmicos); prolonga o QT.',
   'Bacteriostatic macrolide (50S protein synthesis inhibition), active against streptococci, staphylococci, Helicobacter pylori, Legionella and atypical mycobacteria. Potent CYP3A4 and P-glycoprotein inhibitor — raises levels of many drugs (statins, colchicine, anticoagulants, antiarrhythmics); prolongs QT.',
   E'Tratamento de infeções respiratórias (faringite, sinusite, bronquite, pneumonia adquirida na comunidade).\nInfeções da pele e tecidos moles.\nErradicação de Helicobacter pylori (em associação, com inibidor da bomba de protões).\nInfeções por micobactérias atípicas (em associação, por especialista).',
   E'Treatment of respiratory infections (pharyngitis, sinusitis, bronchitis, community-acquired pneumonia).\nSkin and soft tissue infections.\nEradication of Helicobacter pylori (in combination, with a proton pump inhibitor).\nAtypical mycobacterial infections (in combination, under specialist care).',
   E'Náuseas, vómitos, diarreia, dor abdominal ou sabor metálico na boca.\nDor de cabeça, tonturas ou insónia.\nErupção cutânea ou comichão.\nAlterações do ritmo cardíaco (prolongamento do QT) — palpitações, desmaios.\nRaramente, lesão do fígado (icterícia, urina escura) ou perda auditiva.\nProcure ajuda se tiver palpitações, desmaios, icterícia ou diarreia persistente com sangue.',
   E'Nausea, vomiting, diarrhoea, abdominal pain or a metallic taste in the mouth.\nHeadache, dizziness or insomnia.\nSkin rash or itching.\nHeart rhythm changes (QT prolongation) — palpitations, fainting.\nRarely, liver injury (jaundice, dark urine) or hearing loss.\nSeek help if you have palpitations, fainting, jaundice or persistent bloody diarrhoea.',
   E'Não tomar com medicamentos que prolongam o QT nem com fármacos metabolizados pelo CYP3A4 (ex.: algumas estatinas, colchicina, certos antiarrítmicos) sem revisão médica.\nInformar o médico de toda a medicação — o risco de interações é elevado.\nTomar com alimentos para reduzir o desconforto gástrico.\nEm doentes com doença hepática ou renal, o médico ajusta a dose.\nNão usar em gravidez sem indicação médica.',
   E'Do not take with medicines that prolong QT or with CYP3A4-metabolised drugs (e.g. some statins, colchicine, certain antiarrhythmics) without medical review.\nTell your doctor about all medication — the risk of interactions is high.\nTake with food to reduce stomach discomfort.\nIn patients with liver or kidney disease, the doctor adjusts the dose.\nDo not use in pregnancy without medical advice.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Claritromicina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d5be5f12-6392-4d7d-ab23-ebc205ac1a85 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Clarithromycin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d5be5f12-6392-4d7d-ab23-ebc205ac1a85 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('cetoconazol',
   'O cetoconazol é um antifúngico (azólico) usado por via oral em infeções fúngicas profundas ou graves que não respondem a outros tratamentos. Bloqueia fortemente a eliminação de muitos medicamentos, pelo que o risco de interações graves é elevado e exige supervisão médica apertada.',
   'Ketoconazole is an antifungal (azole) used orally for deep or severe fungal infections that have not responded to other treatments. It strongly blocks the elimination of many medicines, so the risk of serious interactions is high and close medical supervision is required.',
   'Antifúngico azólico oral (inibição da síntese do ergosterol) para infeções sistémicas graves (blastomicose, coccidioidomicose, histoplasmose) quando não há alternativa. Inibidor potente do CYP3A4 — múltiplas contraindicações por interação (prolonga o QT; hepatotoxicidade e supressão adrenal dose-dependentes).',
   'Oral azole antifungal (ergosterol synthesis inhibition) for serious systemic infections (blastomycosis, coccidioidomycosis, histoplasmosis) when no alternative exists. Potent CYP3A4 inhibitor — multiple interaction contraindications (prolongs QT; dose-dependent hepatotoxicity and adrenal suppression).',
   E'Tratamento de infeções fúngicas sistémicas graves (blastomicose, coccidioidomicose, histoplasmose) em doentes sem alternativa terapêutica.\nTratamento de micoses cutâneas e mucosas resistentes (em situações selecionadas, por especialista).',
   E'Treatment of severe systemic fungal infections (blastomycosis, coccidioidomycosis, histoplasmosis) in patients without a therapeutic alternative.\nTreatment of resistant cutaneous and mucosal mycoses (in selected situations, under specialist care).',
   E'Náuseas, vómitos, diarreia ou dor abdominal.\nComichão, erupção cutânea ou dor de cabeça.\nLesão do fígado (hepatite) — cansaço, icterícia, urina escura; avaliar imediatamente.\nAlterações do ritmo cardíaco (prolongamento do QT) — palpitações, desmaios.\nSupressão adrenal ou de hormonas sexuais — fadiga, queda de libido, ginecomastia.\nProcure ajuda se tiver icterícia, palpitações ou cansaço extremo.',
   E'Nausea, vomiting, diarrhoea or abdominal pain.\nItching, skin rash or headache.\nLiver injury (hepatitis) — fatigue, jaundice, dark urine; assess immediately.\nHeart rhythm changes (QT prolongation) — palpitations, fainting.\nAdrenal or sex hormone suppression — fatigue, loss of libido, gynaecomastia.\nSeek help if you have jaundice, palpitations or extreme fatigue.',
   E'Requerer supervisão médica — não tomar com muitos medicamentos (ex.: estatinas, colchicina, certos antiarrítmicos, benzodiazepinas) por risco de toxicidade.\nAnálises ao fígado antes e durante o tratamento.\nTomar com alimento ácido (ex.: sumo de laranja ou bebida de cola) para melhorar a absorção.\nEvitar antiácidos 2 horas antes ou depois da toma.\nInformar o médico se tem doença hepática, adrenal ou ritmo cardíaco irregular.',
   E'Requires medical supervision — do not take with many medicines (e.g. statins, colchicine, certain antiarrhythmics, benzodiazepines) due to toxicity risk.\nLiver tests before and during treatment.\nTake with an acidic drink (e.g. orange juice or cola) to improve absorption.\nAvoid antacids for 2 hours before or after the dose.\nTell your doctor if you have liver disease, adrenal problems or an irregular heart rhythm.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Cetoconazol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f162e616-21b4-49b1-b437-15e21001a6f0 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Ketoconazole label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f162e616-21b4-49b1-b437-15e21001a6f0 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('antiacidos',
   'Os antiácidos são medicamentos que neutralizam o ácido do estômago, usados para alívio rápido de azia, indigestão e desconforto gástrico. São eficazes para sintomas ocasionais, mas podem reduzir a absorção de outros medicamentos se forem tomados ao mesmo tempo.',
   'Antacids are medicines that neutralise stomach acid, used for fast relief of heartburn, indigestion and stomach discomfort. They are effective for occasional symptoms, but can reduce the absorption of other medicines if taken at the same time.',
   'Grupo de sais básicos (hidróxido de alumínio e magnésio, com simeticone) que neutralizam rapidamente o ácido gástrico. Uso sintomático de curta duração; o alumínio obstipa e o magnésio laxea; podem quelar e reduzir a absorção de muitos fármacos (separação de 2 horas).',
   'Group of basic salts (aluminium and magnesium hydroxide, with simethicone) that rapidly neutralise gastric acid. Short-term symptomatic use; aluminium constipates and magnesium loosens stools; they can chelate and reduce absorption of many drugs (2-hour separation).',
   E'Alívio rápido de azia e indigestão ácida.\nAlívio do desconforto gástrico associado a excessos alimentares ou bebidas.\nAlívio sintomático ocasional de refluxo gastroesofágico ligeiro.',
   E'Fast relief of heartburn and acid indigestion.\nRelief of stomach discomfort after heavy meals or drinks.\nOccasional symptomatic relief of mild gastro-oesophageal reflux.',
   E'Obstipação (preparações com alumínio).\nDiarreia ou fezes moles (preparações com magnésio).\nRaramente, náuseas ou desconforto abdominal.\nCom uso prolongado e doses altas: desequilíbrios de minerais (fósforo, cálcio, magnésio) — cansaço, fraqueza.\nProcure ajuda se tiver dor abdominal intensa, vómitos persistentes ou fezes escuras.',
   E'Constipation (aluminium-containing products).\nDiarrhoea or loose stools (magnesium-containing products).\nRarely, nausea or abdominal discomfort.\nWith prolonged use and high doses: mineral imbalances (phosphorus, calcium, magnesium) — fatigue, weakness.\nSeek help if you have severe abdominal pain, persistent vomiting or dark stools.',
   E'Tomar apenas para sintomas ocasionais — não usar em contínuo sem aconselhamento.\nSeparar 2 horas da toma de outros medicamentos (reduzem a sua absorção).\nCautela em doentes com insuficiência renal (acumulação de alumínio/magnésio).\nSe os sintomas persistirem mais de 2 semanas, procure avaliação médica.\nEvitar se tem hemorragia digestiva ou dor abdominal intensa sem diagnóstico.',
   E'Take only for occasional symptoms — do not use continuously without advice.\nSeparate by 2 hours from other medicines (they reduce absorption).\nCaution in patients with kidney failure (aluminium/magnesium accumulation).\nIf symptoms last more than 2 weeks, seek medical evaluation.\nAvoid if you have digestive bleeding or severe undiagnosed abdominal pain.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Antiácidos (hidróxido de alumínio e magnésio + dimeticone): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=23539e7e-a723-460f-892f-dac5bbbb9b16 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Antacids label (aluminium and magnesium hydroxide + dimethicone): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=23539e7e-a723-460f-892f-dac5bbbb9b16 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('itraconazol',
   'O itraconazol é um antifúngico usado em infeções fúngicas da pele, unhas, boca e em infeções fúngicas profundas. É eficaz, mas interage com muitos medicamentos e pode afetar o coração e o fígado, pelo que deve ser usado com supervisão médica.',
   'Itraconazole is an antifungal used for fungal infections of the skin, nails and mouth and for deep fungal infections. It is effective, but interacts with many medicines and can affect the heart and liver, so it should be used under medical supervision.',
   'Antifúngico triazólico (inibição da síntese do ergosterol) de largo espetro: dermatofitoses, onicomicose, candidíase, aspergilose, blastomicose e histoplasmose. Inibidor potente do CYP3A4 — muitas interações; prolonga o QT, pode agravar a insuficiência cardíaca e causar hepatotoxicidade.',
   'Broad-spectrum triazole antifungal (ergosterol synthesis inhibition): dermatophytoses, onychomycosis, candidiasis, aspergillosis, blastomycosis and histoplasmosis. Potent CYP3A4 inhibitor — many interactions; prolongs QT, can worsen heart failure and cause hepatotoxicity.',
   E'Infeções fúngicas da pele e unhas (dermatofitoses, onicomicose).\nCandidíase oral, vaginal ou esofágica (quando outros antifúngicos não são adequados).\nInfeções fúngicas profundas (aspergilose, blastomicose, histoplasmose), por especialista.',
   E'Fungal infections of the skin and nails (dermatophytoses, onychomycosis).\nOral, vaginal or oesophageal candidiasis (when other antifungals are not suitable).\nDeep fungal infections (aspergillosis, blastomycosis, histoplasmosis), under specialist care.',
   E'Náuseas, vómitos, diarreia, dor abdominal ou desconforto gástrico.\nDor de cabeça, tonturas ou cansaço.\nErupção cutânea ou comichão.\nInchaço das pernas, falta de ar ou aumento rápido de peso — pode agravar a insuficiência cardíaca.\nLesão do fígado — icterícia, urina escura, cansaço.\nProcure ajuda se tiver palpitações, desmaios, inchaço ou icterícia.',
   E'Nausea, vomiting, diarrhoea, abdominal pain or stomach discomfort.\nHeadache, dizziness or fatigue.\nSkin rash or itching.\nSwelling of the legs, shortness of breath or rapid weight gain — may worsen heart failure.\nLiver injury — jaundice, dark urine, fatigue.\nSeek help if you have palpitations, fainting, swelling or jaundice.',
   E'Informar o médico de toda a medicação — muitas interações graves (estatinas, colchicina, anticoagulantes, benzodiazepinas).\nAs cápsulas tomam-se com alimentos; a solução oral em jejum.\nAnálises ao fígado e vigilância de sintomas cardíacos durante o tratamento.\nNão usar em doentes com insuficiência cardíaca ou hepática sem avaliação médica.\nNão tomar com antiácidos 2 horas antes ou depois.',
   E'Tell your doctor about all medication — many serious interactions (statins, colchicine, anticoagulants, benzodiazepines).\nCapsules are taken with food; the oral solution on an empty stomach.\nLiver tests and monitoring for cardiac symptoms during treatment.\nDo not use in patients with heart or liver failure without medical evaluation.\nDo not take with antacids for 2 hours before or after.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Itraconazol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=68165d90-953c-e2f5-e053-2a91aa0ada25 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Itraconazole label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=68165d90-953c-e2f5-e053-2a91aa0ada25 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('aspirina',
   'A aspirina (ácido acetilsalicílico) é usada para dor, febre e inflamação em doses normais, e em doses baixas para prevenir ataques cardíacos e AVC. É um dos medicamentos mais usados, mas aumenta o risco de hemorragia e de irritação do estômago.',
   'Aspirin (acetylsalicylic acid) is used for pain, fever and inflammation at regular doses, and at low doses to prevent heart attacks and stroke. It is one of the most used medicines, but increases the risk of bleeding and stomach irritation.',
   'AINE antiagregante plaquetário irreversível (inibição da COX-1/COX-2 e do tromboxano A2). Em dose antiagregante (75–100 mg) indicado na prevenção secundária cardiovascular e no síndrome coronário agudo; em dose analgésica/anti-inflamatória para dor, febre e processos inflamatórios. Risco de hemorragia GI e eventos trombóticos cardiovasculares, como outros AINE.',
   'Antiplatelet NSAID with irreversible COX-1/COX-2 inhibition (thromboxane A2). At antiplatelet dose (75–100 mg) indicated for secondary cardiovascular prevention and acute coronary syndrome; at analgesic/anti-inflammatory doses for pain, fever and inflammatory conditions. Risk of GI bleeding and cardiovascular thrombotic events, as with other NSAIDs.',
   E'Prevenção de ataques cardíacos e AVC em doentes de alto risco (dose baixa, 75–100 mg/dia, prescrita pelo médico).\nTratamento do enfarte agudo do miocárdio e prevenção de re-enfarte.\nAlívio da dor ligeira a moderada e redução da febre (dose analgésica).\nAlívio de processos inflamatórios ligeiros (artrose, tendinites), em doses adequadas.',
   E'Prevention of heart attacks and stroke in high-risk patients (low dose, 75–100 mg/day, prescribed by the doctor).\nTreatment of acute myocardial infarction and prevention of recurrence.\nRelief of mild to moderate pain and reduction of fever (analgesic dose).\nRelief of mild inflammatory conditions (osteoarthritis, tendinitis), at adequate doses.',
   E'Irritação do estômago, azia, náuseas ou desconforto abdominal.\nHemorragia gastrointestinal — fezes escuras, vómitos com sangue; risco aumentado com álcool ou outros AINE.\nZumbidos, tonturas ou perda auditiva (doses altas).\nNódoas negras ou hemorragias fáceis (efeito antiagregante).\nRaramente, reações alérgicas graves (asma, inchaço).\nProcure ajuda imediata se tiver fezes escuras, vómitos com sangue, dor no peito ou inchaço súbito.',
   E'Stomach irritation, heartburn, nausea or abdominal discomfort.\nGastrointestinal bleeding — dark stools, vomiting blood; risk increased with alcohol or other NSAIDs.\nTinnitus, dizziness or hearing loss (high doses).\nEasy bruising or bleeding (antiplatelet effect).\nRarely, serious allergic reactions (asthma, swelling).\nSeek immediate help if you have dark stools, vomiting blood, chest pain or sudden swelling.',
   E'Em dose baixa para prevenção cardiovascular, tomar sempre à mesma hora; não interromper sem falar com o médico.\nNão dar a crianças ou adolescentes com febre ou infeções virais (risco de síndrome de Reye).\nComer antes de tomar para reduzir a irritação gástrica.\nEvitar álcool e outros anti-inflamatórios em simultâneo (risco de hemorragia).\nAvisar o médico antes de cirurgias ou extrações dentárias.',
   E'At low dose for cardiovascular prevention, take at the same time every day; do not stop without talking to your doctor.\nDo not give to children or teenagers with fever or viral infections (risk of Reye syndrome).\nTake with food to reduce stomach irritation.\nAvoid alcohol and other anti-inflammatories at the same time (bleeding risk).\nTell your doctor before surgery or dental extractions.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Aspirina (comprimido gastrorresistente 81 mg): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=277723db-3578-4842-92eb-2de325f87649 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Aspirin label (81 mg enteric-coated tablet): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=277723db-3578-4842-92eb-2de325f87649 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('voriconazol',
   'O voriconazol é um antifúngico usado em infeções fúngicas graves, especialmente aspergilose invasiva em doentes imunodeprimidos. É muito eficaz, mas exige monitorização apertada: afeta a visão, o fígado e interage com muitos medicamentos.',
   'Voriconazole is an antifungal used for serious fungal infections, especially invasive aspergillosis in immunocompromised patients. It is very effective, but requires close monitoring: it affects vision, the liver and interacts with many medicines.',
   'Antifúngico triazólico de segunda geração (inibição da síntese do ergosterol), tratamento de primeira linha da aspergilose invasiva; também candidemia, candidíase esofágica e infeções por Scedosporium/Fusarium. Inibidor do CYP2C19/3A4 com farmacocinética não linear; exige monitorização terapêutica e vigilância ocular, hepática e do QT.',
   'Second-generation triazole antifungal (ergosterol synthesis inhibition), first-line treatment of invasive aspergillosis; also candidaemia, oesophageal candidiasis and Scedosporium/Fusarium infections. CYP2C19/3A4 inhibitor with non-linear pharmacokinetics; requires therapeutic drug monitoring and ocular, hepatic and QT surveillance.',
   E'Tratamento de primeira linha da aspergilose invasiva em adultos e crianças (≥2 anos).\nTratamento da candidemia e de candidíase invasiva (em doentes sem neutropenia).\nCandidíase esofágica grave.\nInfeções fúngicas por Scedosporium e Fusarium resistentes a outros antifúngicos.',
   E'First-line treatment of invasive aspergillosis in adults and children (≥2 years).\nTreatment of candidaemia and invasive candidiasis (in non-neutropenic patients).\nSevere oesophageal candidiasis.\nFungal infections by Scedosporium and Fusarium resistant to other antifungals.',
   E'Alterações da visão — visão desfocada, alteração das cores, fotofobia (muito frequente; geralmente transitórias).\nNáuseas, vómitos, diarreia ou dor abdominal.\nErupção cutânea e fotossensibilidade (queimaduras solares fáceis).\nAlterações do fígado — icterícia, urina escura, cansaço.\nAlucinações, palpitações ou alterações do ritmo cardíaco.\nProcure ajuda se tiver icterícia, alterações graves da visão, palpitações ou reação cutânea extensa.',
   E'Visual changes — blurred vision, colour disturbance, photophobia (very common; usually transient).\nNausea, vomiting, diarrhoea or abdominal pain.\nSkin rash and photosensitivity (easy sunburn).\nLiver changes — jaundice, dark urine, fatigue.\nHallucinations, palpitations or heart rhythm changes.\nSeek help if you have jaundice, severe visual changes, palpitations or an extensive skin reaction.',
   E'Requerer monitorização: análises ao fígado, níveis do fármaco no sangue e vigilância da visão.\nEvitar exposição solar e usar protetor — risco de queimaduras e de cancro de pele com uso prolongado.\nNão conduzir à noite se tiver alterações da visão.\nInformar o médico de toda a medicação — muitas interações (contraindicado com rifampicina, carbamazepina, alguns antiarrítmicos).\nNunca tomar com erva-de-São-João.',
   E'Requires monitoring: liver tests, blood drug levels and vision surveillance.\nAvoid sun exposure and use sunscreen — risk of burns and skin cancer with prolonged use.\nDo not drive at night if you have visual changes.\nTell your doctor about all medication — many interactions (contraindicated with rifampicin, carbamazepine, some antiarrhythmics).\nNever take with St. John wort.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Voriconazol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c620b2d7-3c2b-4252-8cfc-2f322d624435 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Voriconazole label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c620b2d7-3c2b-4252-8cfc-2f322d624435 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('cloroquina',
   'A cloroquina é um medicamento antimalárico, usado no tratamento e prevenção da malária em zonas onde o parasita ainda é sensível. Também é usada em algumas doenças reumáticas e lúpus. Requer vigilância oftalmológica em tratamentos prolongados.',
   'Chloroquine is an antimalarial medicine, used to treat and prevent malaria in areas where the parasite is still sensitive. It is also used in some rheumatic diseases and lupus. Long-term treatment requires eye monitoring.',
   'Antimalárico 4-aminoquinolina (acumulação no vacúolo digestivo do parasita e inibição da polimerização da hemozoína). Tratamento e profilaxia da malária por estirpes sensíveis; amebíase extra-intestinal (em associação); doenças autoimunes (lúpus, artrite reumatoide). Risco de retinopatia cumulativa, prolongamento do QT e cardiotoxicidade; tóxico em sobredosagem.',
   '4-aminoquinoline antimalarial (accumulation in the parasite digestive vacuole and inhibition of haemozoin polymerisation). Treatment and prophylaxis of malaria due to sensitive strains; extra-intestinal amoebiasis (in combination); autoimmune diseases (lupus, rheumatoid arthritis). Risk of cumulative retinopathy, QT prolongation and cardiotoxicity; toxic in overdose.',
   E'Tratamento da malária aguda por Plasmodium falciparum e outras espécies sensíveis.\nProfilaxia da malária em zonas sem resistência à cloroquina.\nAmebíase extra-intestinal (em associação com outros fármacos).\nLúpus eritematoso e artrite reumatoide (em situações selecionadas, por especialista).',
   E'Treatment of acute malaria due to sensitive Plasmodium falciparum and other species.\nProphylaxis of malaria in areas without chloroquine resistance.\nExtra-intestinal amoebiasis (in combination with other drugs).\nSystemic lupus erythematosus and rheumatoid arthritis (in selected situations, under specialist care).',
   E'Náuseas, vómitos, diarreia ou dor abdominal.\nDor de cabeça, tonturas ou comichão na pele.\nAlterações da visão (visão desfocada, dificuldade em ler) — com uso prolongado, risco de retinopatia.\nFraqueza muscular ou alterações do ritmo cardíaco (palpitações).\nAlterações da pele (pigmentação) e do cabelo.\nProcure ajuda se tiver alterações da visão, palpitações, convulsões ou confusão.',
   E'Nausea, vomiting, diarrhoea or abdominal pain.\nHeadache, dizziness or skin itching.\nVisual changes (blurred vision, difficulty reading) — with long-term use, risk of retinopathy.\nMuscle weakness or heart rhythm changes (palpitations).\nSkin (pigmentation) and hair changes.\nSeek help if you have visual changes, palpitations, seizures or confusion.',
   E'Em tratamento prolongado (lúpus/artrite), exames oftalmológicos periódicos.\nManter fora do alcance das crianças — sobredosagem é extremamente tóxica (1 comprimido pode ser fatal numa criança).\nInformar o médico se tem doença renal, hepática, cardíaca, psoríase, défice de G6PD ou epilepsia.\nEvitar com outros medicamentos que prolongam o QT sem revisão médica.\nEm gravidez, só com indicação médica.',
   E'With long-term treatment (lupus/arthritis), periodic eye examinations.\nKeep out of reach of children — overdose is extremely toxic (one tablet can be fatal in a child).\nTell your doctor if you have kidney, liver, heart disease, psoriasis, G6PD deficiency or epilepsy.\nAvoid other QT-prolonging medicines without medical review.\nIn pregnancy, only on medical advice.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Cloroquina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=06c69e2b-211b-4746-9f3a-f86d36520570 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Chloroquine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=06c69e2b-211b-4746-9f3a-f86d36520570 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('fluconazol',
   'O fluconazol é um antifúngico usado em infeções por Candida (boca, garganta, vagina) e em infeções fúngicas graves, incluindo a meningite por criptococo. É eficaz e bem tolerado, mas pode afetar o fígado e interagir com muitos medicamentos.',
   'Fluconazole is an antifungal used for Candida infections (mouth, throat, vagina) and for serious fungal infections, including cryptococcal meningitis. It is effective and well tolerated, but can affect the liver and interact with many medicines.',
   'Antifúngico triazólico (inibição da síntese do ergosterol) com boa penetração no SNC. Indicado em candidíase mucocutânea e sistémica, meningite criptocócica e profilaxia em transplantados. Inibidor do CYP2C9/2C19/3A4 — aumenta níveis de varfarina, fenitoína, sulfonilureias e estatinas; prolonga o QT.',
   'Triazole antifungal (ergosterol synthesis inhibition) with good CNS penetration. Indicated for mucocutaneous and systemic candidiasis, cryptococcal meningitis and prophylaxis in transplant recipients. CYP2C9/2C19/3A4 inhibitor — raises levels of warfarin, phenytoin, sulfonylureas and statins; prolongs QT.',
   E'Candidíase oral, esofágica e vaginal.\nCandidíase sistémica e candidemia.\nMeningite criptocócica (tratamento e prevenção de recidivas).\nProfilaxia de infeções fúngicas em doentes imunodeprimidos (transplantados, após quimioterapia).',
   E'Oral, oesophageal and vaginal candidiasis.\nSystemic candidiasis and candidaemia.\nCryptococcal meningitis (treatment and prevention of relapse).\nProphylaxis of fungal infections in immunocompromised patients (transplant recipients, after chemotherapy).',
   E'Náuseas, vómitos, diarreia, dor abdominal ou alteração do paladar.\nDor de cabeça, tonturas ou erupção cutânea.\nAlterações do fígado — icterícia, urina escura, cansaço.\nAlterações do ritmo cardíaco (prolongamento do QT) — palpitações, desmaios.\nQueda de cabelo (raro, com uso prolongado).\nProcure ajuda se tiver icterícia, palpitações ou reação cutânea extensa.',
   E'Nausea, vomiting, diarrhoea, abdominal pain or taste changes.\nHeadache, dizziness or skin rash.\nLiver changes — jaundice, dark urine, fatigue.\nHeart rhythm changes (QT prolongation) — palpitations, fainting.\nHair loss (rare, with prolonged use).\nSeek help if you have jaundice, palpitations or an extensive skin reaction.',
   E'Informar o médico de toda a medicação — interage com anticoagulantes, antidiabéticos orais e muitos outros.\nAnálises ao fígado durante tratamentos prolongados.\nEm doses altas ou gravidez, usar apenas com indicação médica.\nTomar a dose à mesma hora todos os dias.\nNão tomar com outros medicamentos que prolongam o QT sem revisão médica.',
   E'Tell your doctor about all medication — interacts with anticoagulants, oral antidiabetics and many others.\nLiver tests during prolonged treatment.\nAt high doses or in pregnancy, use only on medical advice.\nTake the dose at the same time every day.\nDo not take other QT-prolonging medicines without medical review.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Fluconazol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7961c029-746c-48c3-888b-8f8344102873 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Fluconazole label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7961c029-746c-48c3-888b-8f8344102873 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('sertralina',
   'A sertralina é um antidepressivo (ISRS) usado na depressão, ansiedade, perturbação obsessivo-compulsiva e outras perturbações. É eficaz, mas os efeitos demoram algumas semanas e podem surgir náuseas, insónia ou alterações do desejo sexual no início.',
   'Sertraline is an antidepressant (SSRI) used for depression, anxiety, obsessive-compulsive disorder and other conditions. It is effective, but effects take a few weeks and nausea, insomnia or changes in sexual desire may occur at the start.',
   'ISRS (inibição seletiva da recaptação da serotonina). Indicado na depressão major, perturbação de pânico, TOC, perturbação de ansiedade social, PTSD e perturbação disfórica pré-menstrual. Risco de síndrome serotoninérgica (com IMAO, linezolida, tramadol), aumento do risco hemorrágico, hiponatremia e ideação suicida em jovens no início do tratamento.',
   'SSRI (selective serotonin reuptake inhibitor). Indicated in major depression, panic disorder, OCD, social anxiety disorder, PTSD and premenstrual dysphoric disorder. Risk of serotonin syndrome (with MAOIs, linezolid, tramadol), increased bleeding risk, hyponatraemia and suicidal ideation in young people early in treatment.',
   E'Depressão major.\nPerturbação de pânico, com ou sem agorafobia.\nPerturbação obsessivo-compulsiva (adultos e crianças).\nPerturbação de ansiedade social e perturbação de stress pós-traumático.\nPerturbação disfórica pré-menstrual.',
   E'Major depression.\nPanic disorder, with or without agoraphobia.\nObsessive-compulsive disorder (adults and children).\nSocial anxiety disorder and post-traumatic stress disorder.\nPremenstrual dysphoric disorder.',
   E'Náuseas, diarreia, perda de apetite ou boca seca (frequentes no início).\nInsónia ou sonolência, tonturas, cansaço.\nAlterações do desejo ou função sexual.\nSudorese, tremores ou dor de cabeça.\nRaramente: hemorragias fáceis, hiponatremia (confusão, fraqueza), agitação intensa.\nProcure ajuda se tiver pensamentos de autoagressão, febre com rigidez muscular ou confusão súbita.',
   E'Nausea, diarrhoea, loss of appetite or dry mouth (common at the start).\nInsomnia or drowsiness, dizziness, fatigue.\nChanges in sexual desire or function.\nSweating, tremors or headache.\nRarely: easy bleeding, hyponatraemia (confusion, weakness), severe agitation.\nSeek help if you have thoughts of self-harm, fever with muscle stiffness or sudden confusion.',
   E'Os efeitos benéficos demoram 2–4 semanas — não interromper precocemente.\nNunca combinar com outros antidepressivos, tramadol, linezolida ou erva-de-São-João sem supervisão médica (síndrome serotoninérgica).\nNão parar abruptamente — a suspensão deve ser gradual.\nEvitar álcool.\nInformar o médico se está grávida, a amamentar ou se planeia engravidar.',
   E'Beneficial effects take 2–4 weeks — do not stop early.\nNever combine with other antidepressants, tramadol, linezolid or St. John wort without medical supervision (serotonin syndrome).\nDo not stop abruptly — withdrawal must be gradual.\nAvoid alcohol.\nTell your doctor if you are pregnant, breastfeeding or planning pregnancy.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Sertralina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=91e24d17-ff0a-449c-9472-b9df74c98456 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Sertraline label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=91e24d17-ff0a-449c-9472-b9df74c98456 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('dexametasona',
   'A dexametasona é um corticosteroide potente usado para reduzir inflamação e modular o sistema imunitário em muitas doenças (alergias, asma, doenças reumáticas, tumores). Usada em tratamentos curtos ou prolongados; exige vigilância médica, sobretudo em uso prolongado.',
   'Dexamethasone is a potent corticosteroid used to reduce inflammation and modulate the immune system in many diseases (allergies, asthma, rheumatic diseases, tumours). Used in short or long courses; requires medical supervision, especially with prolonged use.',
   'Corticosteroide glucocorticóide sintético (agonista do recetor dos glucocorticóides) com potente ação anti-inflamatória e imunossupressora e atividade mineralocorticoide mínima. Uso sistémico em alergias graves, doenças respiratórias, reumáticas, gastrointestinais, oncológicas e hematológicas; supressão do eixo HPA dependente da dose e duração — suspensão sempre gradual.',
   'Synthetic glucocorticoid corticosteroid (glucocorticoid receptor agonist) with potent anti-inflammatory and immunosuppressive action and minimal mineralocorticoid activity. Systemic use in severe allergies, respiratory, rheumatic, gastrointestinal, oncological and haematological diseases; HPA axis suppression depends on dose and duration — always taper when stopping.',
   E'Doenças alérgicas e inflamatórias graves (asma, rinite alérgica grave, anafilaxia).\nDoenças reumáticas e autoimunes (artrite reumatoide, lúpus) em situações agudas.\nDoenças respiratórias (exacerbações de DPOC, pneumonite).\nTerapêutica adjuvante em tumores (cerebrais, hematológicos) e na prevenção de vómitos da quimioterapia.\nEdema cerebral (hipertensão intracraniana).',
   E'Severe allergic and inflammatory diseases (asthma, severe allergic rhinitis, anaphylaxis).\nRheumatic and autoimmune diseases (rheumatoid arthritis, lupus) in acute situations.\nRespiratory diseases (COPD exacerbations, pneumonitis).\nAdjuvant therapy in tumours (brain, haematological) and prevention of chemotherapy-induced vomiting.\nCerebral oedema (raised intracranial pressure).',
   E'Aumento do apetite, ganho de peso e retenção de líquidos (inchaço).\nInsónia, irritabilidade, agitação ou alterações do humor.\nAumento da tensão arterial e da glicemia (açúcar no sangue).\nIrritação gástrica, azia — risco de úlcera em uso prolongado.\nOsteoporose, fraqueza muscular e catarata com uso prolongado.\nProcure ajuda se tiver dor abdominal intensa, fezes escuras, inchaço súbito ou alterações do humor graves.',
   E'Increased appetite, weight gain and fluid retention (swelling).\nInsomnia, irritability, agitation or mood changes.\nRaised blood pressure and blood glucose (sugar).\nStomach irritation, heartburn — ulcer risk with prolonged use.\nOsteoporosis, muscle weakness and cataracts with prolonged use.\nSeek help if you have severe abdominal pain, dark stools, sudden swelling or severe mood changes.',
   E'Não suspender abruptamente após uso prolongado — a dose reduz-se gradualmente.\nTomar com alimentos para reduzir a irritação gástrica; considerar proteção gástrica com o médico.\nVigiar glicemia e tensão arterial durante o tratamento.\nEvitar vacinas vivas durante o tratamento.\nUsar a menor dose eficaz pelo menor tempo possível; avisar o médico antes de qualquer cirurgia.',
   E'Do not stop abruptly after prolonged use — the dose is reduced gradually.\nTake with food to reduce stomach irritation; consider stomach protection with your doctor.\nMonitor blood glucose and blood pressure during treatment.\nAvoid live vaccines during treatment.\nUse the lowest effective dose for the shortest time; tell your doctor before any surgery.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Dexametasona (injetável): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Dexamethasone label (injectable): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('fluoxetina',
   'A fluoxetina é um antidepressivo (ISRS) usado na depressão, perturbação obsessivo-compulsiva, bulimia e síndrome pré-menstrual. É eficaz, mas demora algumas semanas a atuar e pode causar náuseas, insónia e alterações do desejo sexual no início.',
   'Fluoxetine is an antidepressant (SSRI) used for depression, obsessive-compulsive disorder, bulimia and premenstrual syndrome. It is effective, but takes a few weeks to work and may cause nausea, insomnia and changes in sexual desire at the start.',
   'ISRS (inibição seletiva da recaptação da serotonina), com metabolito ativo de meia-vida muito longa (norfluoxetina). Indicado na depressão major, TOC, bulimia nervosa e perturbação disfórica pré-menstrual. Risco de síndrome serotoninérgica, hiponatremia, hemorragia e prolongamento do QT em doses altas; meia-vida longa — cautela ao trocar de antidepressivo.',
   'SSRI (selective serotonin reuptake inhibitor) with an active metabolite with a very long half-life (norfluoxetine). Indicated in major depression, OCD, bulimia nervosa and premenstrual dysphoric disorder. Risk of serotonin syndrome, hyponatraemia, bleeding and QT prolongation at high doses; long half-life — caution when switching antidepressants.',
   E'Depressão major.\nPerturbação obsessivo-compulsiva.\nBulimia nervosa.\nPerturbação disfórica pré-menstrual.',
   E'Major depression.\nObsessive-compulsive disorder.\nBulimia nervosa.\nPremenstrual dysphoric disorder.',
   E'Náuseas, diarreia, perda de apetite ou boca seca (frequentes no início).\nInsónia, nervosismo, ansiedade ou agitação.\nDor de cabeça, tonturas, cansaço.\nAlterações do desejo ou função sexual.\nSudorese, tremores ou sonolência.\nProcure ajuda se tiver pensamentos de autoagressão, febre com rigidez muscular, confusão ou agitação intensa.',
   E'Nausea, diarrhoea, loss of appetite or dry mouth (common at the start).\nInsomnia, nervousness, anxiety or agitation.\nHeadache, dizziness, fatigue.\nChanges in sexual desire or function.\nSweating, tremors or drowsiness.\nSeek help if you have thoughts of self-harm, fever with muscle stiffness, confusion or severe agitation.',
   E'Os efeitos benéficos demoram 2–4 semanas — não interromper precocemente.\nNunca combinar com IMAO, linezolida, tramadol ou erva-de-São-João (síndrome serotoninérgica).\nNão parar abruptamente.\nEvitar álcool e condução se sentir sonolência.\nInformar o médico se está grávida, a amamentar ou se planeia engravidar.',
   E'Beneficial effects take 2–4 weeks — do not stop early.\nNever combine with MAOIs, linezolid, tramadol or St. John wort (serotonin syndrome).\nDo not stop abruptly.\nAvoid alcohol and driving if you feel drowsy.\nTell your doctor if you are pregnant, breastfeeding or planning pregnancy.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Fluoxetina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=583c5021-2948-7db4-e063-6294a90ae7dc — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Fluoxetine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=583c5021-2948-7db4-e063-6294a90ae7dc — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('quinina',
   'A quinina é um medicamento antimalárico usado no tratamento da malária por Plasmodium falciparum não complicada, geralmente em associação. Em doses baixas é usada para cãibras musculares noturnas, uso que tem vindo a ser restringido pelos riscos.',
   'Quinine is an antimalarial medicine used to treat uncomplicated Plasmodium falciparum malaria, usually in combination. At low doses it is used for nocturnal leg cramps, a use that has been restricted because of its risks.',
   'Alcaloide da cinchona com atividade esquizonticida sanguínea contra o P. falciparum (mecanismo relacionado com a cloroquina). Tratamento da malária não complicada por estirpes resistentes à cloroquina (em associação com outros antimaláricos); uso em cãibras musculares noturnas restrito pelos riscos (arritmias, trombocitopenia, cinconismo). Prolonga o QT; risco de hipoglicemia.',
   'Cinchona alkaloid with blood schizonticidal activity against P. falciparum (mechanism related to chloroquine). Treatment of uncomplicated malaria due to chloroquine-resistant strains (in combination with other antimalarials); use in nocturnal leg cramps restricted by its risks (arrhythmias, thrombocytopenia, cinchonism). Prolongs QT; risk of hypoglycaemia.',
   E'Tratamento da malária não complicada por Plasmodium falciparum resistente à cloroquina (em associação).\nTratamento da babesiose (em associação, por especialista).\nUso restrito em cãibras musculares noturnas (apenas por indicação médica, quando outros tratamentos falharam).',
   E'Treatment of uncomplicated malaria due to chloroquine-resistant Plasmodium falciparum (in combination).\nTreatment of babesiosis (in combination, under specialist care).\nRestricted use in nocturnal leg cramps (only on medical advice, when other treatments have failed).',
   E'Cinconismo: zumbidos, dor de cabeça, náuseas, alterações da visão e da audição (dose-dependente).\nHipoglicemia — sudação, tremores, confusão, desmaios.\nAlterações do ritmo cardíaco (prolongamento do QT) — palpitações.\nHemorragias fáceis ou manchas roxas (trombocitopenia) — avaliar imediatamente.\nReações alérgicas graves, incluindo erupção cutânea extensa.\nProcure ajuda imediata se tiver manchas roxas, palpitações, desmaios ou confusão.',
   E'Cinchonism: tinnitus, headache, nausea, visual and hearing changes (dose-dependent).\nHypoglycaemia — sweating, tremors, confusion, fainting.\nHeart rhythm changes (QT prolongation) — palpitations.\nEasy bleeding or purple spots (thrombocytopenia) — assess immediately.\nSerious allergic reactions, including extensive skin rash.\nSeek immediate help if you have purple spots, palpitations, fainting or confusion.',
   E'Tomar com alimentos para reduzir o desconforto gástrico.\nEvitar com outros medicamentos que prolongam o QT ou com digoxina sem revisão médica.\nVigiar sintomas de hipoglicemia, sobretudo em jejum ou com diabetes.\nNão usar em doentes com défice de G6PD, miastenia gravis, neurite ótica ou arritmias sem avaliação médica.\nEm gravidez, usar apenas por indicação médica (malária).',
   E'Take with food to reduce stomach discomfort.\nAvoid other QT-prolonging medicines or digoxin without medical review.\nMonitor for symptoms of hypoglycaemia, especially when fasting or with diabetes.\nDo not use in patients with G6PD deficiency, myasthenia gravis, optic neuritis or arrhythmias without medical evaluation.\nIn pregnancy, use only on medical advice (malaria).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Quinina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1f32f05c-a215-40be-b951-e41a7b54a8a0 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Quinine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1f32f05c-a215-40be-b951-e41a7b54a8a0 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('litio',
   'O lítio é um estabilizador do humor usado na perturbação bipolar, sobretudo para prevenir crises de mania e depressão. É muito eficaz, mas tem uma janela terapêutica estreita — exige análises regulares e vigilância médica apertada.',
   'Lithium is a mood stabiliser used in bipolar disorder, mainly to prevent episodes of mania and depression. It is very effective, but has a narrow therapeutic window — it requires regular blood tests and close medical supervision.',
   'Estabilizador do humor (mecanismo multifatorial sobre vias do inositol e da glicogénio-sintase-quinase 3). Primeira linha na manutenção da perturbação bipolar (reduz mania e suicídio); potenciador na depressão unipolar resistente. Índice terapêutico estreito (0,6–1,2 mmol/L); toxicidade renal, tiroideia e neurológica; muitas interações com AINE, diuréticos e IECA.',
   'Mood stabiliser (multifactorial mechanism on inositol pathways and glycogen synthase kinase 3). First line in maintenance of bipolar disorder (reduces mania and suicide); augmentation in resistant unipolar depression. Narrow therapeutic index (0.6–1.2 mmol/L); renal, thyroid and neurological toxicity; many interactions with NSAIDs, diuretics and ACE inhibitors.',
   E'Tratamento e prevenção de episódios de mania na perturbação bipolar.\nPrevenção de episódios depressivos na perturbação bipolar.\nPotenciação em depressão unipolar resistente (por especialista).',
   E'Treatment and prevention of manic episodes in bipolar disorder.\nPrevention of depressive episodes in bipolar disorder.\nAugmentation in resistant unipolar depression (under specialist care).',
   E'Tremor fino das mãos, sede aumentada e urinar mais (frequentes).\nNáuseas, diarreia ou aumento de peso.\nSintomas de toxicidade — vómitos, diarreia grave, fala arrastada, confusão, tremores grosseiros, desequilíbrio: emergência médica.\nAlterações da tiroide (fadiga, variações de peso, intolerância ao frio).\nAlterações da função renal em uso prolongado.\nProcure ajuda imediata se tiver vómitos, confusão, tremores intensos ou desequilíbrio.',
   E'Fine tremor of the hands, increased thirst and urination (common).\nNausea, diarrhoea or weight gain.\nSymptoms of toxicity — vomiting, severe diarrhoea, slurred speech, confusion, coarse tremors, imbalance: medical emergency.\nThyroid changes (fatigue, weight changes, cold intolerance).\nKidney function changes with prolonged use.\nSeek immediate help if you have vomiting, confusion, severe tremors or imbalance.',
   E'Análises regulares (lítio no sangue, função renal e tiroideia) — nunca falhar.\nManter ingestão de água e sal estáveis; desidratação, febre ou calor aumentam o risco de toxicidade.\nEvitar anti-inflamatórios (AINE) — aumentam o lítio no sangue.\nNunca alterar a dose por sua conta.\nInformar o médico de toda a medicação (diuréticos, IECAs e muitos outros interagem).',
   E'Regular blood tests (serum lithium, kidney and thyroid function) — never miss them.\nKeep water and salt intake stable; dehydration, fever or heat increase toxicity risk.\nAvoid anti-inflammatories (NSAIDs) — they raise blood lithium.\nNever change the dose on your own.\nTell your doctor about all medication (diuretics, ACE inhibitors and many others interact).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Lítio: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=582697c1-063f-366f-e063-6294a90a8d1b — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Lithium label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=582697c1-063f-366f-e063-6294a90a8d1b — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('mefloquina',
   'A mefloquina é um medicamento antimalárico usado na prevenção e no tratamento da malária em zonas com resistência à cloroquina. Pode causar efeitos neuropsiquiátricos (tonturas, insónia, ansiedade, pesadelos) — em casos raros, mais graves.',
   'Mefloquine is an antimalarial medicine used to prevent and treat malaria in areas with chloroquine resistance. It can cause neuropsychiatric effects (dizziness, insomnia, anxiety, nightmares) — in rare cases, more serious ones.',
   'Antimalárico 4-quinolinometanol (relacionado com a quinina) para profilaxia e tratamento de malária não complicada por estirpes sensíveis. Risco importante de efeitos neuropsiquiátricos (depressão, psicose, convulsões) e de prolongamento do QT; contraindicado na doença psiquiátrica ativa ou história de convulsões.',
   '4-quinolinemethanol antimalarial (related to quinine) for prophylaxis and treatment of uncomplicated malaria due to sensitive strains. Significant risk of neuropsychiatric effects (depression, psychosis, seizures) and QT prolongation; contraindicated in active psychiatric disease or history of seizures.',
   E'Profilaxia da malária em zonas com resistência à cloroquina (semanal).\nTratamento da malária aguda não complicada por estirpes sensíveis.\nTratamento de seguimento após terapêutica intravenosa da malária grave.',
   E'Prophylaxis of malaria in areas with chloroquine resistance (weekly).\nTreatment of acute uncomplicated malaria due to sensitive strains.\nFollow-up treatment after intravenous therapy of severe malaria.',
   E'Tonturas, dor de cabeça, insónia ou pesadelos.\nNáuseas, vómitos, diarreia ou dor abdominal.\nAnsiedade, depressão, agitação ou alterações do humor.\nAlterações do ritmo cardíaco (prolongamento do QT) — palpitações.\nRaramente: convulsões, psicose, reações cutâneas graves.\nProcure ajuda imediata se tiver pensamentos de autoagressão, convulsões, palpitações ou reação cutânea extensa.',
   E'Dizziness, headache, insomnia or nightmares.\nNausea, vomiting, diarrhoea or abdominal pain.\nAnxiety, depression, agitation or mood changes.\nHeart rhythm changes (QT prolongation) — palpitations.\nRarely: seizures, psychosis, severe skin reactions.\nSeek immediate help if you have thoughts of self-harm, seizures, palpitations or an extensive skin reaction.',
   E'Não usar em doentes com depressão ativa ou recente, ansiedade generalizada, psicose, esquizofrenia, história de convulsões ou arritmias.\nOs efeitos neuropsiquiátricos podem persistir após a suspensão — avisar o médico.\nEvitar com halofantrina ou cetoconazol (risco de arritmias graves).\nTomar com alimentos e com água; não tomar em jejum.\nSe viajar, começar a profilaxia 2–3 semanas antes para tolerar o fármaco.',
   E'Do not use in patients with active or recent depression, generalised anxiety, psychosis, schizophrenia, history of seizures or arrhythmias.\nNeuropsychiatric effects can persist after stopping — tell your doctor.\nAvoid halofantrine or ketoconazole (risk of serious arrhythmias).\nTake with food and water; do not take on an empty stomach.\nIf travelling, start prophylaxis 2–3 weeks before to tolerate the drug.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Mefloquina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=09716a24-d7da-42b2-af29-c03a1b6670bd — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Mefloquine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=09716a24-d7da-42b2-af29-c03a1b6670bd — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('ritonavir',
   'O ritonavir é um medicamento antirretroviral usado no tratamento da infeção pelo VIH, quase sempre em doses baixas para potenciar outros antirretrovirais (boost). Bloqueia fortemente a eliminação de muitos medicamentos, pelo que as interações são frequentes e exigem revisão médica.',
   'Ritonavir is an antiretroviral medicine used to treat HIV infection, almost always at low doses to boost other antiretrovirals. It strongly blocks the elimination of many medicines, so interactions are frequent and require medical review.',
   'Inibidor da protease do VIH-1; em dose baixa (100 mg) usado como potenciador farmacocinético de outros inibidores da protease e de alguns inibidores da integrase. Inibidor potente do CYP3A4 e da glicoproteína-P — inúmeras contraindicações por interação (muitos fármacos elevam níveis de forma perigosa); perfil metabólico (dislipidemia, hiperglicemia) e gastrointestinal.',
   'HIV-1 protease inhibitor; at low dose (100 mg) used as a pharmacokinetic booster of other protease inhibitors and some integrase inhibitors. Potent CYP3A4 and P-glycoprotein inhibitor — numerous interaction contraindications (many drugs reach dangerous levels); metabolic profile (dyslipidaemia, hyperglycaemia) and gastrointestinal effects.',
   E'Tratamento da infeção pelo VIH-1, em associação com outros antirretrovirais.\nPotenciação farmacocinética (boost) de outros inibidores da protease ou de inibidores da integrase (dose baixa).\nProfilaxia pós-exposição ao VIH (em associação, em regime de urgência).',
   E'Treatment of HIV-1 infection, in combination with other antiretrovirals.\nPharmacokinetic boosting of other protease inhibitors or integrase inhibitors (low dose).\nPost-exposure prophylaxis of HIV (in combination, as an emergency regimen).',
   E'Náuseas, vómitos, diarreia ou dor abdominal (frequentes no início).\nFormigueiro à volta da boca ou das extremidades.\nAumento do colesterol e triglicéridos.\nAumento do açúcar no sangue ou resistência à insulina.\nAlterações da distribuição da gordura (lipodistrofia) e lesão hepática (icterícia) com uso prolongado.\nProcure ajuda se tiver icterícia, dor abdominal intensa ou sintomas de diabetes (sede, urinar muito).',
   E'Nausea, vomiting, diarrhoea or abdominal pain (common at the start).\nTingling around the mouth or extremities.\nIncreased cholesterol and triglycerides.\nIncreased blood sugar or insulin resistance.\nChanges in fat distribution (lipodystrophy) and liver injury (jaundice) with prolonged use.\nSeek help if you have jaundice, severe abdominal pain or symptoms of diabetes (thirst, frequent urination).',
   E'Informar o médico de TODA a medicação, incluindo sem receita e plantas — muitas interações graves (contraindicado com rifampicina, algumas estatinas, midazolam, ergotamínicos).\nTomar com alimentos para reduzir o desconforto gástrico.\nAnálises regulares (fígado, glicemia, lípidos).\nNão interromper o tratamento sem falar com o médico.\nUsar sempre preservativo — o tratamento não elimina o risco de transmissão do VIH.',
   E'Tell your doctor about ALL medication, including over-the-counter and herbal products — many serious interactions (contraindicated with rifampicin, some statins, midazolam, ergot alkaloids).\nTake with food to reduce stomach discomfort.\nRegular tests (liver, blood glucose, lipids).\nDo not stop treatment without talking to your doctor.\nAlways use a condom — treatment does not eliminate the risk of HIV transmission.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Ritonavir: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d2f8c6ba-5e06-4b03-8ca5-b4fd7e5a8925 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012) e guidelines internacionais de VIH',
   'DailyMed/FDA (NIH/NLM) — approved Ritonavir label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d2f8c6ba-5e06-4b03-8ca5-b4fd7e5a8925 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012) and international HIV guidelines'),
  ('isoniazida',
   'A isoniazida é um antibiótico usado no tratamento e na prevenção da tuberculose, sempre em associação com outros fármacos. É eficaz, mas pode afetar o fígado e os nervos — exige vigilância e suplementação de vitamina B6.',
   'Isoniazid is an antibiotic used to treat and prevent tuberculosis, always in combination with other drugs. It is effective, but can affect the liver and the nerves — it requires monitoring and vitamin B6 supplementation.',
   'Antituberculoso de primeira linha (inibição da síntese de ácidos micólicos da parede das micobactérias), bactericida para bacilos em multiplicação. Sempre em associação no tratamento da tuberculose; também na infeção latente. Hepatotoxicidade dose/idade-dependente, neuropatia periférica (prevenível com piridoxina) e interações com fenitoína/carbamazepina por inibição enzimática.',
   'First-line antituberculosis drug (inhibition of mycolic acid synthesis in the mycobacterial wall), bactericidal for multiplying bacilli. Always in combination in tuberculosis treatment; also in latent infection. Dose/age-dependent hepatotoxicity, peripheral neuropathy (preventable with pyridoxine) and interactions with phenytoin/carbamazepine via enzyme inhibition.',
   E'Tratamento da tuberculose pulmonar e extrapulmonar (sempre em associação).\nTratamento da infeção tuberculosa latente (profilaxia).\nProfilaxia de contacto em grupos de risco (por indicação médica).',
   E'Treatment of pulmonary and extrapulmonary tuberculosis (always in combination).\nTreatment of latent tuberculosis infection (prophylaxis).\nContact prophylaxis in risk groups (on medical advice).',
   E'Náuseas, vómitos ou desconforto abdominal.\nFormigueiro, dormência ou dor nas mãos e pés (neuropatia periférica).\nLesão do fígado — cansaço, icterícia, urina escura; avaliar imediatamente.\nErupção cutânea, febre ou dores articulares.\nRaramente: anemia, alterações do humor ou convulsões.\nProcure ajuda imediata se tiver icterícia, dormência progressiva, febre ou reação cutânea.',
   E'Nausea, vomiting or abdominal discomfort.\nTingling, numbness or pain in the hands and feet (peripheral neuropathy).\nLiver injury — fatigue, jaundice, dark urine; assess immediately.\nSkin rash, fever or joint pain.\nRarely: anaemia, mood changes or seizures.\nSeek immediate help if you have jaundice, progressive numbness, fever or a skin reaction.',
   E'Tomar sempre com vitamina B6 (piridoxina) para prevenir a neuropatia.\nEvitar álcool — risco hepático.\nAnálises ao fígado antes e durante o tratamento.\nTomar em jejum (1 hora antes ou 2 horas depois das refeições) para melhor absorção.\nInformar o médico se tem doença hepática, renal ou epilepsia.',
   E'Always take with vitamin B6 (pyridoxine) to prevent neuropathy.\nAvoid alcohol — liver risk.\nLiver tests before and during treatment.\nTake on an empty stomach (1 hour before or 2 hours after meals) for better absorption.\nTell your doctor if you have liver, kidney disease or epilepsy.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Isoniazida: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=93252cc8-c8d4-401b-bde5-ca8a3b57651e — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Isoniazid label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=93252cc8-c8d4-401b-bde5-ca8a3b57651e — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('artemeter-lumefantrina',
   'O arteméter + lumefantrina é um medicamento combinado contra a malária (ACT), usado no tratamento da malária não complicada por Plasmodium falciparum. É eficaz e rápido, mas deve tomar-se com alimentos e não se usa em malária grave.',
   'Artemether + lumefantrine is a combined antimalarial medicine (ACT), used to treat uncomplicated Plasmodium falciparum malaria. It is effective and fast, but must be taken with food and is not used in severe malaria.',
   'Combinação artemisinínica (ACT): arteméter (derivado da artemisinina, ação rápida) + lumefantrina (ação mais lenta), sinérgicos contra o P. falciparum. Tratamento da malária não complicada (≥2 meses, ≥5 kg); a absorção da lumefantrina aumenta com alimentos gordos; indutores do CYP3A4 reduzem a eficácia; prolonga o QT.',
   'Artemisinin-based combination (ACT): artemether (artemisinin derivative, fast action) + lumefantrine (slower action), synergistic against P. falciparum. Treatment of uncomplicated malaria (≥2 months, ≥5 kg); lumefantrine absorption increases with fatty food; CYP3A4 inducers reduce efficacy; prolongs QT.',
   E'Tratamento da malária aguda não complicada por Plasmodium falciparum (adultos e crianças ≥2 meses, ≥5 kg).\nTratamento de malária mista (P. falciparum com outras espécies) em zonas endémicas.',
   E'Treatment of acute uncomplicated Plasmodium falciparum malaria (adults and children ≥2 months, ≥5 kg).\nTreatment of mixed malaria (P. falciparum with other species) in endemic areas.',
   E'Dor de cabeça, tonturas, cansaço ou fraqueza (frequentes).\nPerda de apetite, náuseas, vómitos, dor abdominal ou diarreia.\nPalpitações, insónia ou alterações do sono.\nProlongamento do intervalo QT no ECG (geralmente sem sintomas).\nReações alérgicas (erupção cutânea, comichão) — raras.\nProcure ajuda se tiver palpitações, desmaios, vómitos persistentes ou reação cutânea extensa.',
   E'Headache, dizziness, fatigue or weakness (common).\nLoss of appetite, nausea, vomiting, abdominal pain or diarrhoea.\nPalpitations, insomnia or sleep changes.\nQT interval prolongation on ECG (usually without symptoms).\nAllergic reactions (skin rash, itching) — rare.\nSeek help if you have palpitations, fainting, persistent vomiting or an extensive skin reaction.',
   E'Tomar com alimentos (de preferência com alguma gordura) — melhora a absorção e a eficácia.\nFazer o esquema completo de 6 doses ao longo de 3 dias, mesmo que se sinta melhor.\nNão usar em malária grave nem na prevenção da malária.\nSe vomitar nos 30–60 minutos após a toma, falar com o médico (pode ser preciso repetir a dose).\nEvitar com rifampicina, carbamazepina ou outros indutores do CYP3A4 sem revisão médica.',
   E'Take with food (preferably with some fat) — improves absorption and efficacy.\nComplete the full 6-dose course over 3 days, even if you feel better.\nDo not use in severe malaria or for malaria prevention.\nIf you vomit within 30–60 minutes of the dose, talk to your doctor (the dose may need repeating).\nAvoid rifampicin, carbamazepine or other CYP3A4 inducers without medical review.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Coartem (arteméter + lumefantrina): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7866ec19-dfac-47d4-a53f-511a12643cbf — com referência adicional: OMS — Directrizes para a malária; Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Coartem label (artemether + lumefantrine): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7866ec19-dfac-47d4-a53f-511a12643cbf — with additional reference: WHO — Guidelines for malaria; Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('cotrimoxazol',
   'O cotrimoxazol é um antibiótico combinado (sulfametoxazol + trimetoprim) usado em infeções urinárias, respiratórias e na prevenção e tratamento de infeções por Pneumocystis em doentes imunodeprimidos. É eficaz, mas pode causar reações alérgicas graves e afetar a medula óssea.',
   'Co-trimoxazole is a combined antibiotic (sulfamethoxazole + trimethoprim) used for urinary and respiratory infections and for prevention and treatment of Pneumocystis infections in immunocompromised patients. It is effective, but can cause serious allergic reactions and affect the bone marrow.',
   'Associação fixa sulfametoxazol (sulfonamida, antagonista do PABA) + trimetoprim (inibidor da di-hidrofolato-redutase) — sinergismo bactericida em duas etapas da síntese de folatos. UTI, infeções respiratórias, shigelose e Pneumocystis jirovecii (tratamento e profilaxia). Risco de reações cutâneas graves (SJS/TEN), discrasias sanguíneas, hipercaliemia e fotossensibilidade.',
   'Fixed combination sulfamethoxazole (sulfonamide, PABA antagonist) + trimethoprim (dihydrofolate reductase inhibitor) — synergistic bactericidal action on two steps of folate synthesis. UTIs, respiratory infections, shigellosis and Pneumocystis jirovecii (treatment and prophylaxis). Risk of severe skin reactions (SJS/TEN), blood dyscrasias, hyperkalaemia and photosensitivity.',
   E'Infeções do trato urinário (em situações selecionadas).\nInfeções respiratórias, otite média e sinusite (em situações selecionadas).\nTratamento e profilaxia da pneumonia por Pneumocystis jirovecii (doentes imunodeprimidos).\nToxoplasmose (em associação, por especialista) e shigelose.',
   E'Urinary tract infections (in selected situations).\nRespiratory infections, otitis media and sinusitis (in selected situations).\nTreatment and prophylaxis of Pneumocystis jirovecii pneumonia (immunocompromised patients).\nToxoplasmosis (in combination, under specialist care) and shigellosis.',
   E'Náuseas, vómitos, diarreia ou perda de apetite (frequentes).\nErupção cutânea, comichão ou fotossensibilidade.\nReações cutâneas graves (SJS/TEN, DRESS) — febre com erupção extensa, bolhas: emergência.\nAlterações do sangue (anemia, leucopenia, trombocitopenia) — cansaço, infeções, hemorragias fáceis.\nAumento do potássio ou hipoglicemia em doentes de risco.\nProcure ajuda imediata se tiver erupção extensa com bolhas, febre alta, manchas roxas ou palidez.',
   E'Nausea, vomiting, diarrhoea or loss of appetite (common).\nSkin rash, itching or photosensitivity.\nSevere skin reactions (SJS/TEN, DRESS) — fever with extensive rash, blisters: emergency.\nBlood changes (anaemia, leucopenia, thrombocytopenia) — fatigue, infections, easy bleeding.\nRaised potassium or hypoglycaemia in at-risk patients.\nSeek immediate help if you have an extensive rash with blisters, high fever, purple spots or pallor.',
   E'Parar o tratamento e procurar ajuda ao primeiro sinal de erupção cutânea ou reação alérgica.\nBeber bastante água para prevenir cristais nos rins.\nEvitar exposição solar e usar protetor.\nEvitar em doentes com défice de folatos, anemia megaloblástica ou insuficiência renal grave sem ajuste.\nNão usar em crianças <2 meses nem no 3.º trimestre de gravidez sem indicação médica.',
   E'Stop treatment and seek help at the first sign of a skin rash or allergic reaction.\nDrink plenty of water to prevent kidney crystals.\nAvoid sun exposure and use sunscreen.\nAvoid in patients with folate deficiency, megaloblastic anaemia or severe kidney failure without adjustment.\nDo not use in children <2 months or in the 3rd trimester of pregnancy without medical advice.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Sulfametoxazol + Trimetoprim (cotrimoxazol): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=08500fcb-dbec-4ac2-91c3-189d27907ec0 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Sulfamethoxazole + Trimethoprim label (co-trimoxazole): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=08500fcb-dbec-4ac2-91c3-189d27907ec0 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('hidroclorotiazida',
   'A hidroclorotiazida é um diurético usado no tratamento da tensão arterial alta e do inchaço (edema) associado a insuficiência cardíaca, doença do fígado ou rins. É eficaz e bem tolerada, mas exige vigilância de eletrólitos e do açúcar no sangue.',
   'Hydrochlorothiazide is a diuretic used to treat high blood pressure and swelling (oedema) associated with heart failure, liver or kidney disease. It is effective and well tolerated, but requires monitoring of electrolytes and blood sugar.',
   'Diurético tiazídico (inibição do cotransportador Na+/Cl- no túbulo contorcido distal). Anti-hipertensor de primeira linha e no edema da insuficiência cardíaca, cirrose e terapêutica corticoide/estrogénica. Risco de hipocaliemia, hiponatremia, hiperuricemia, hiperglicemia e hipercalcemia; associado a fotossensibilidade e a cancro de pele não melanoma com dose cumulativa alta.',
   'Thiazide diuretic (inhibition of the Na+/Cl- cotransporter in the distal convoluted tubule). First-line antihypertensive and for oedema in heart failure, cirrhosis and corticosteroid/oestrogen therapy. Risk of hypokalaemia, hyponatraemia, hyperuricaemia, hyperglycaemia and hypercalcaemia; associated with photosensitivity and non-melanoma skin cancer with high cumulative dose.',
   E'Tratamento da hipertensão arterial (isolado ou em associação).\nTratamento do edema associado a insuficiência cardíaca, cirrose hepática e terapêutica com corticosteroides ou estrogénios.\nEdema de origem renal (síndrome nefrótico, glomerulonefrite aguda, insuficiência renal crónica), em situações selecionadas.',
   E'Treatment of hypertension (alone or in combination).\nTreatment of oedema associated with heart failure, hepatic cirrhosis and corticosteroid or oestrogen therapy.\nOedema of renal origin (nephrotic syndrome, acute glomerulonephritis, chronic kidney failure), in selected situations.',
   E'Aumento da vontade de urinar e sede (início do tratamento).\nTonturas ou tensão baixa ao levantar (hipotensão ortostática).\nDesiquilíbrios de eletrólitos: potássio baixo (fraqueza, cãibras), sódio baixo (confusão).\nAumento do ácido úrico (gota) ou do açúcar no sangue.\nFotossensibilidade e, com dose cumulativa alta, risco aumentado de cancro de pele não melanoma.\nProcure ajuda se tiver fraqueza intensa, cãibras, confusão, palpitações ou visão súbita alterada.',
   E'Increased urination and thirst (start of treatment).\nDizziness or low blood pressure on standing (orthostatic hypotension).\nElectrolyte imbalances: low potassium (weakness, cramps), low sodium (confusion).\nIncreased uric acid (gout) or blood sugar.\nPhotosensitivity and, with high cumulative dose, increased risk of non-melanoma skin cancer.\nSeek help if you have severe weakness, cramps, confusion, palpitations or sudden visual changes.',
   E'Análises periódicas de eletrólitos, açúcar, ácido úrico e função renal.\nTomar de manhã para evitar acordar à noite para urinar.\nUsar protetor solar e vigiar a pele (risco de cancro de pele com uso prolongado).\nCautela com álcool e com outros anti-hipertensores (hipotensão).\nInformar o médico se tem gota, diabetes, doença renal ou alergia a sulfonamidas.',
   E'Periodic tests of electrolytes, sugar, uric acid and kidney function.\nTake in the morning to avoid waking at night to urinate.\nUse sunscreen and monitor the skin (skin cancer risk with prolonged use).\nCaution with alcohol and other antihypertensives (hypotension).\nTell your doctor if you have gout, diabetes, kidney disease or sulfonamide allergy.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Hidroclorotiazida: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=31a3d1cb-0f52-4818-965d-7584374bb23e — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Hydrochlorothiazide label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=31a3d1cb-0f52-4818-965d-7584374bb23e — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('hidroxicloroquina',
   'A hidroxicloroquina é um medicamento usado no lúpus, na artrite reumatoide e no tratamento e prevenção da malária. Em uso prolongado pode afetar a retina, pelo que exige exames oftalmológicos periódicos.',
   'Hydroxychloroquine is a medicine used in lupus, rheumatoid arthritis and for the treatment and prevention of malaria. With prolonged use it can affect the retina, so periodic eye examinations are required.',
   'Antimalárico 4-aminoquinolina com atividade imunomoduladora (aumento do pH dos endossomas, redução da apresentação antigénica e de citocinas pró-inflamatórias). Primeira linha no lúpus eritematoso sistémico e na artrite reumatoide ligeira; malária por estirpes sensíveis. Risco dose-cumulativo de retinopatia (exames oftalmológicos periódicos), cardiotoxicidade, miopatia e prolongamento do QT.',
   '4-aminoquinoline antimalarial with immunomodulatory activity (endosomal pH increase, reduced antigen presentation and pro-inflammatory cytokines). First line in systemic lupus erythematosus and mild rheumatoid arthritis; malaria due to sensitive strains. Cumulative-dose risk of retinopathy (periodic eye examinations), cardiotoxicity, myopathy and QT prolongation.',
   E'Lúpus eritematoso sistémico (tratamento e prevenção de recidivas).\nArtrite reumatoide ligeira.\nTratamento e prevenção da malária por estirpes sensíveis à cloroquina/hidroxicloroquina.\nPorfíria cutânea tardia (por especialista).',
   E'Systemic lupus erythematosus (treatment and prevention of relapse).\nMild rheumatoid arthritis.\nTreatment and prevention of malaria due to strains sensitive to chloroquine/hydroxychloroquine.\nPorphyria cutanea tarda (under specialist care).',
   E'Náuseas, diarreia, dor abdominal ou perda de apetite.\nErupção cutânea, comichão ou pigmentação da pele.\nAlterações da visão (dificuldade em ler, perda de campo visual) — sinal de retinopatia; avaliar de imediato.\nFraqueza muscular, cãibras ou fadiga.\nAlterações do ritmo cardíaco (palpitações) em uso prolongado.\nProcure ajuda se tiver alterações da visão, palpitações, fraqueza súbita ou reação cutânea extensa.',
   E'Nausea, diarrhoea, abdominal pain or loss of appetite.\nSkin rash, itching or skin pigmentation.\nVisual changes (difficulty reading, loss of visual field) — sign of retinopathy; assess immediately.\nMuscle weakness, cramps or fatigue.\nHeart rhythm changes (palpitations) with prolonged use.\nSeek help if you have visual changes, palpitations, sudden weakness or an extensive skin reaction.',
   E'Exames oftalmológicos antes de iniciar e periodicamente durante o tratamento (risco de retinopatia).\nTomar com alimentos para reduzir o desconforto gástrico.\nNunca exceder a dose prescrita — sobredosagem é muito tóxica.\nInformar o médico se tem doença renal, hepática, cardíaca, psoríase, défice de G6PD ou epilepsia.\nEm gravidez, usar apenas por indicação médica (lúpus/malária).',
   E'Eye examinations before starting and periodically during treatment (retinopathy risk).\nTake with food to reduce stomach discomfort.\nNever exceed the prescribed dose — overdose is very toxic.\nTell your doctor if you have kidney, liver, heart disease, psoriasis, G6PD deficiency or epilepsy.\nIn pregnancy, use only on medical advice (lupus/malaria).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Hidroxicloroquina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ebe00e35-ed3d-40f4-9a93-a37b0da01ddb — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Hydroxychloroquine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ebe00e35-ed3d-40f4-9a93-a37b0da01ddb — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('tramadol',
   'O tramadol é um analgésico opioide usado na dor moderada a intensa quando outros analgésicos não são suficientes. É eficaz, mas pode causar dependência, sonolência, náuseas e, em casos raros, convulsões ou síndrome serotoninérgica.',
   'Tramadol is an opioid analgesic used for moderate to severe pain when other painkillers are not enough. It is effective, but can cause dependence, drowsiness, nausea and, in rare cases, seizures or serotonin syndrome.',
   'Analgésico opioide atípico (agonista fraco do recetor mu + inibição da recaptação de serotonina e noradrenalina), pró-fármaco do M1 (metabolizado pelo CYP2D6). Dor moderada a intensa. Depressão respiratória, dependência, risco de convulsões (limiar baixado) e de síndrome serotoninérgica; metabolizadores ultrarrápidos do CYP2D6 — toxicidade opioide; contraindicado <12 anos.',
   'Atypical opioid analgesic (weak mu receptor agonist + serotonin and noradrenaline reuptake inhibition), prodrug of M1 (metabolised by CYP2D6). Moderate to severe pain. Respiratory depression, dependence, risk of seizures (lowered threshold) and serotonin syndrome; CYP2D6 ultrarapid metabolisers — opioid toxicity; contraindicated under 12 years.',
   E'Tratamento da dor moderada a intensa, quando os analgésicos simples não são suficientes.\nDor aguda e crónica não oncológica e oncológica (em esquemas titulados pelo médico).',
   E'Treatment of moderate to severe pain, when simple analgesics are not enough.\nAcute and chronic non-cancer and cancer pain (in doctor-titrated regimens).',
   E'Tonturas, sonolência, náuseas, vómitos ou obstipação (frequentes).\nDor de cabeça, sudação, boca seca ou cansaço.\nRisco de dependência e de sintomas de privação se suspender abruptamente.\nRaramente: convulsões, síndrome serotoninérgica (agitação, febre, rigidez), depressão respiratória.\nProcure ajuda imediata se tiver sonolência excessiva com respiração lenta, convulsões, confusão ou febre com rigidez.',
   E'Dizziness, drowsiness, nausea, vomiting or constipation (common).\nHeadache, sweating, dry mouth or fatigue.\nRisk of dependence and withdrawal symptoms if stopped abruptly.\nRarely: seizures, serotonin syndrome (agitation, fever, stiffness), respiratory depression.\nSeek immediate help if you have excessive drowsiness with slow breathing, seizures, confusion or fever with stiffness.',
   E'Não conduzir nem operar máquinas enquanto sentir sonolência.\nNão combinar com álcool, benzodiazepinas, outros opioides ou sedativos sem revisão médica.\nNunca combinar com antidepressivos (ISRS, IMAO), linezolida ou outros serotoninérgicos — síndrome serotoninérgica.\nNão usar em crianças <12 anos nem após amigdalectomia em <18 anos.\nNão aumentar a dose por conta própria — risco de dependência e sobredosagem.',
   E'Do not drive or operate machinery while feeling drowsy.\nDo not combine with alcohol, benzodiazepines, other opioids or sedatives without medical review.\nNever combine with antidepressants (SSRIs, MAOIs), linezolid or other serotonergic drugs — serotonin syndrome.\nDo not use in children under 12 years or after tonsillectomy in under-18s.\nDo not increase the dose on your own — risk of dependence and overdose.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Tramadol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9f0e33bd-65f8-446a-886f-e7e16a142ce5 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Tramadol label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9f0e33bd-65f8-446a-886f-e7e16a142ce5 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('diidroartemisinina-piperaquina',
   'A diidroartemisinina + piperaquina é um medicamento combinado contra a malária (ACT), usado no tratamento da malária não complicada por Plasmodium falciparum em adultos e crianças. Prolonga o intervalo QT do coração, pelo que não se combina com outros fármacos que tenham o mesmo efeito.',
   'Dihydroartemisinin + piperaquine is a combined antimalarial medicine (ACT), used to treat uncomplicated Plasmodium falciparum malaria in adults and children. It prolongs the QT interval of the heart, so it must not be combined with other drugs that have the same effect.',
   'Combinação artemisinínica (ACT): diidroartemisinina (derivado da artemisinina, ação rápida) + piperaquina (ação prolongada, meia-vida ~22 dias). Tratamento da malária não complicada por P. falciparum (≥6 meses, ≥5 kg). A piperaquina prolonga o QT e é um inibidor ligeiro/substrato do CYP3A4 — contraindicações por interação e vigilância cardíaca; tomar em jejum.',
   'Artemisinin-based combination (ACT): dihydroartemisinin (artemisinin derivative, fast action) + piperaquine (prolonged action, half-life ~22 days). Treatment of uncomplicated P. falciparum malaria (≥6 months, ≥5 kg). Piperaquine prolongs QT and is a mild CYP3A4 inhibitor/substrate — interaction contraindications and cardiac surveillance; take on an empty stomach.',
   E'Tratamento da malária não complicada por Plasmodium falciparum em adultos, adolescentes, crianças e lactentes ≥6 meses e ≥5 kg.\nTratamento de malária mista (P. falciparum com outras espécies) em zonas endémicas.',
   E'Treatment of uncomplicated Plasmodium falciparum malaria in adults, adolescents, children and infants ≥6 months and ≥5 kg.\nTreatment of mixed malaria (P. falciparum with other species) in endemic areas.',
   E'Dor de cabeça, cansaço, fraqueza ou febre (frequentes).\nPerda de apetite, náuseas, vómitos, diarreia ou dor abdominal.\nPalpitações, taquicardia ou alterações do ritmo cardíaco (prolongamento do QT).\nAnemia (cansaço, palidez) — frequente, em parte pela própria malária.\nTosse e sintomas gripais (sobretudo em crianças).\nProcure ajuda se tiver palpitações, desmaios, vómitos persistentes ou palidez acentuada.',
   E'Headache, fatigue, weakness or fever (common).\nLoss of appetite, nausea, vomiting, diarrhoea or abdominal pain.\nPalpitations, tachycardia or heart rhythm changes (QT prolongation).\nAnaemia (fatigue, pallor) — common, partly due to malaria itself.\nCough and flu-like symptoms (especially in children).\nSeek help if you have palpitations, fainting, persistent vomiting or marked pallor.',
   E'Tomar em jejum (≥3 horas antes ou depois de comer), à mesma hora, 1 dose/dia durante 3 dias.\nNão usar em malária grave nem na prevenção da malária.\nNão combinar com medicamentos que prolongam o QT (antiarrítmicos, alguns antibióticos e antifúngicos, antimaláricos como mefloquina) sem revisão médica.\nContraindicado se história familiar de morte súbita, QT longo congénito, arritmias ou desequilíbrio de eletrólitos.\nNão repetir o tratamento mais de 2 vezes em 12 meses (meia-vida longa da piperaquina).',
   E'Take on an empty stomach (≥3 hours before or after food), at the same time, 1 dose/day for 3 days.\nDo not use in severe malaria or for malaria prevention.\nDo not combine with QT-prolonging medicines (antiarrhythmics, some antibiotics and antifungals, antimalarials such as mefloquine) without medical review.\nContraindicated with a family history of sudden death, congenital long QT, arrhythmias or electrolyte imbalance.\nDo not repeat treatment more than twice in 12 months (long piperaquine half-life).',
   'EMA — SmPC europeia Eurartesim (diidroartemisinina + piperaquina): https://www.ema.europa.eu/en/medicines/human/EPAR/eurartesim — com referência adicional: OMS — Directrizes para a malária; Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'EMA — European SmPC Eurartesim (dihydroartemisinin + piperaquine): https://www.ema.europa.eu/en/medicines/human/EPAR/eurartesim — with additional reference: WHO — Guidelines for malaria; Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('clopidogrel',
   'O clopidogrel é um medicamento que impede a formação de coágulos nas plaquetas, usado após enfarte, AVC ou em doentes com stents, quase sempre em associação com aspirina. Aumenta o risco de hemorragia, pelo que exige precauções antes de cirurgias.',
   'Clopidogrel is a medicine that prevents blood clots forming on platelets, used after heart attack, stroke or in patients with stents, almost always in combination with aspirin. It increases the risk of bleeding, so precautions are required before surgery.',
   'Antiagregante plaquetário tienopiridínico (inibição irreversível do recetor P2Y12 do ADP), pró-fármaco ativado pelo CYP2C19. Síndrome coronário agudo e prevenção secundária de eventos aterotrombóticos (em associação com aspirina ou em alternativa); stents. Risco hemorrágico; eficácia reduzida em metabolizadores lentos do CYP2C19; interação com inibidores da bomba de protões.',
   'Thienopyridine antiplatelet agent (irreversible inhibition of the platelet P2Y12 ADP receptor), prodrug activated by CYP2C19. Acute coronary syndrome and secondary prevention of atherothrombotic events (with aspirin or as an alternative); stents. Bleeding risk; reduced efficacy in CYP2C19 poor metabolisers; interaction with proton pump inhibitors.',
   E'Prevenção de eventos aterotrombóticos (enfarte, AVC, morte cardiovascular) no síndrome coronário agudo — em associação com aspirina.\nPrevenção de eventos em doentes com enfarte recente, AVC recente ou doença arterial periférica.\nPrevenção de trombose de stents coronários (em associação com aspirina).',
   E'Prevention of atherothrombotic events (heart attack, stroke, cardiovascular death) in acute coronary syndrome — in combination with aspirin.\nPrevention of events in patients with recent heart attack, recent stroke or peripheral arterial disease.\nPrevention of coronary stent thrombosis (in combination with aspirin).',
   E'Nódoas negras ou hemorragias fáceis (efeito esperado).\nHemorragia gastrointestinal — fezes escuras, vómitos com sangue.\nDiarreia, dor abdominal ou indigestão.\nErupção cutânea ou comichão.\nRaramente: púrpura trombocitopénica trombótica (febre, manchas roxas, alterações neurológicas), hemorragia intracraniana.\nProcure ajuda imediata se tiver fezes escuras, vómitos com sangue, manchas roxas, dor de cabeça súbita intensa ou fraqueza num lado do corpo.',
   E'Easy bruising or bleeding (expected effect).\nGastrointestinal bleeding — dark stools, vomiting blood.\nDiarrhoea, abdominal pain or indigestion.\nSkin rash or itching.\nRarely: thrombotic thrombocytopenic purpura (fever, purple spots, neurological changes), intracranial bleeding.\nSeek immediate help if you have dark stools, vomiting blood, purple spots, sudden severe headache or weakness on one side of the body.',
   E'Não interromper sem falar com o médico — risco de trombose do stent.\nAvisar antes de cirurgias ou extrações dentárias (suspensão planeada).\nEvitar anti-inflamatórios (AINE) — aumentam o risco de hemorragia.\nFalar com o médico antes de tomar antiácidos ou omeprazol (alguns reduzem o efeito).\nSe tiver hemorragia que não para, procurar ajuda de imediato.',
   E'Do not stop without talking to your doctor — risk of stent thrombosis.\nTell the team before surgery or dental extractions (planned interruption).\nAvoid anti-inflammatories (NSAIDs) — they increase bleeding risk.\nTalk to your doctor before taking antacids or omeprazole (some reduce the effect).\nIf you have bleeding that does not stop, seek immediate help.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Clopidogrel: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c9928956-bb7b-4ec2-bc38-d3c9c4199cae — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Clopidogrel label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c9928956-bb7b-4ec2-bc38-d3c9c4199cae — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('diclofenac',
   'O diclofenac é um anti-inflamatório (AINE) usado na dor e inflamação da artrose, artrite reumatoide e espondilite anquilosante. É eficaz, mas aumenta o risco de eventos cardiovasculares e de hemorragia gástrica — usar a menor dose eficaz pelo menor tempo possível.',
   'Diclofenac is an anti-inflammatory (NSAID) used for pain and inflammation in osteoarthritis, rheumatoid arthritis and ankylosing spondylitis. It is effective, but increases the risk of cardiovascular events and stomach bleeding — use the lowest effective dose for the shortest time.',
   'AINE não seletivo (inibição da COX-1/COX-2), com potência analgésica e anti-inflamatória. Artrose, artrite reumatoide, espondilite anquilosante. Risco de eventos trombóticos cardiovasculares (especialmente em doses altas), hemorragia/úlcera GI, lesão renal e hepática; contraindicado após cirurgia CABG e no enfarte recente.',
   'Non-selective NSAID (COX-1/COX-2 inhibition), with analgesic and anti-inflammatory potency. Osteoarthritis, rheumatoid arthritis, ankylosing spondylitis. Risk of cardiovascular thrombotic events (especially at high doses), GI bleeding/ulcer, kidney and liver injury; contraindicated after CABG surgery and in recent myocardial infarction.',
   E'Alívio dos sintomas da artrose.\nAlívio dos sintomas da artrite reumatoide.\nAlívio dos sintomas da espondilite anquilosante.\nDor aguda e inflamação de origem músculo-esquelética (por indicação médica).',
   E'Relief of osteoarthritis symptoms.\nRelief of rheumatoid arthritis symptoms.\nRelief of ankylosing spondylitis symptoms.\nAcute pain and inflammation of musculoskeletal origin (on medical advice).',
   E'Irritação do estômago, azia, náuseas ou dor abdominal.\nHemorragia ou úlcera gastrointestinal — fezes escuras, vómitos com sangue; risco maior em idosos.\nRetenção de líquidos, inchaço, aumento da tensão arterial.\nRisco aumentado de enfarte e AVC, sobretudo em doses altas e uso prolongado.\nAlterações do fígado (cansaço, icterícia) ou dos rins (diminuição da urina).\nProcure ajuda imediata se tiver fezes escuras, vómitos com sangue, dor no peito, falta de ar ou inchaço súbito.',
   E'Stomach irritation, heartburn, nausea or abdominal pain.\nGastrointestinal bleeding or ulcer — dark stools, vomiting blood; higher risk in older people.\nFluid retention, swelling, raised blood pressure.\nIncreased risk of heart attack and stroke, especially at high doses and with prolonged use.\nLiver (fatigue, jaundice) or kidney changes (reduced urine).\nSeek immediate help if you have dark stools, vomiting blood, chest pain, shortness of breath or sudden swelling.',
   E'Usar a menor dose eficaz pelo menor tempo possível.\nNão usar após cirurgia cardíaca (CABG) nem em doentes com enfarte recente sem avaliação médica.\nEvitar combinar com outros AINE ou aspirina (risco hemorrágico).\nCautela em idosos e em doentes com doença cardiovascular, renal, hepática ou úlcera prévia.\nNão usar no 3.º trimestre de gravidez.',
   E'Use the lowest effective dose for the shortest time.\nDo not use after heart surgery (CABG) or in patients with a recent heart attack without medical evaluation.\nAvoid combining with other NSAIDs or aspirin (bleeding risk).\nCaution in older people and in patients with cardiovascular, kidney, liver disease or previous ulcer.\nDo not use in the 3rd trimester of pregnancy.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Diclofenac: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=681b6b25-4a28-44f2-8042-d5e01a502116 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Diclofenac label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=681b6b25-4a28-44f2-8042-d5e01a502116 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('eritromicina',
   'A eritromicina é um antibiótico (macrólido) usado em infeções respiratórias, da pele e noutras infeções por bactérias sensíveis, sobretudo em doentes alérgicos à penicilina. Pode afetar o ritmo cardíaco e interage com vários medicamentos.',
   'Erythromycin is an antibiotic (macrolide) used for respiratory and skin infections and other infections caused by susceptible bacteria, especially in patients allergic to penicillin. It can affect the heart rhythm and interacts with several medicines.',
   'Macrólido (inibição da síntese proteica 50S) com espetro semelhante à penicilina — alternativa em alérgicos. Infeções respiratórias, pele, difteria, eritrasma, Legionella, febre reumática e endocardite (profilaxia em alérgicos à penicilina). Inibidor do CYP3A4 e da glicoproteína-P; prolonga o QT (sobretudo IV); risco de estenose pilórica hipertrófica em lactentes.',
   'Macrolide (50S protein synthesis inhibition) with a spectrum similar to penicillin — alternative in allergic patients. Respiratory and skin infections, diphtheria, erythrasma, Legionella, rheumatic fever and endocarditis (prophylaxis in penicillin-allergic patients). CYP3A4 and P-glycoprotein inhibitor; prolongs QT (especially IV); risk of infantile hypertrophic pyloric stenosis.',
   E'Infeções respiratórias (faringite, amigdalite, pneumonia) por bactérias sensíveis, sobretudo em alérgicos à penicilina.\nInfeções da pele e tecidos moles.\nDifteria, eritrasma e doença dos legionários.\nProfilaxia da febre reumática e da endocardite bacteriana (em alérgicos à penicilina).',
   E'Respiratory infections (pharyngitis, tonsillitis, pneumonia) due to susceptible bacteria, especially in penicillin-allergic patients.\nSkin and soft tissue infections.\nDiphtheria, erythrasma and Legionnaires disease.\nProphylaxis of rheumatic fever and bacterial endocarditis (in penicillin-allergic patients).',
   E'Náuseas, vómitos, diarreia ou dor abdominal (frequentes).\nSabor metálico ou desconforto oral.\nAlterações do ritmo cardíaco (prolongamento do QT) — palpitações, desmaios, sobretudo com uso intravenoso.\nReações alérgicas (erupção cutânea, comichão, raramente graves).\nRaramente: perda auditiva reversível (doses altas/insuficiência renal) ou lesão do fígado.\nProcure ajuda se tiver palpitações, desmaios, icterícia ou diarreia persistente com sangue.',
   E'Nausea, vomiting, diarrhoea or abdominal pain (common).\nMetallic taste or oral discomfort.\nHeart rhythm changes (QT prolongation) — palpitations, fainting, especially with intravenous use.\nAllergic reactions (skin rash, itching, rarely serious).\nRarely: reversible hearing loss (high doses/kidney failure) or liver injury.\nSeek help if you have palpitations, fainting, jaundice or persistent bloody diarrhoea.',
   E'Informar o médico de toda a medicação — interage com estatinas, colchicina, anticoagulantes e muitos outros (risco de toxicidade).\nNão combinar com medicamentos que prolongam o QT sem revisão médica.\nTomar com alimentos para reduzir o desconforto gástrico.\nEm bebés, vigiar vómitos persistentes após a toma (risco de estenose pilórica).\nNão usar em gravidez sem indicação médica.',
   E'Tell your doctor about all medication — interacts with statins, colchicine, anticoagulants and many others (toxicity risk).\nDo not combine with QT-prolonging medicines without medical review.\nTake with food to reduce stomach discomfort.\nIn infants, watch for persistent vomiting after a dose (risk of pyloric stenosis).\nDo not use in pregnancy without medical advice.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Eritromicina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ca65a48f-5fe6-4b31-8359-51dbc31f6d4e — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Erythromycin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ca65a48f-5fe6-4b31-8359-51dbc31f6d4e — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('naproxeno',
   'O naproxeno é um anti-inflamatório (AINE) usado na dor, febre e inflamação, incluindo artrose, artrite reumatoide, gota aguda e dores menstruais. É eficaz, mas aumenta o risco de eventos cardiovasculares e de hemorragia gástrica.',
   'Naproxen is an anti-inflammatory (NSAID) used for pain, fever and inflammation, including osteoarthritis, rheumatoid arthritis, acute gout and menstrual pain. It is effective, but increases the risk of cardiovascular events and stomach bleeding.',
   'AINE não seletivo (inibição da COX-1/COX-2) com meia-vida longa (permite 2 tomas/dia). Artrose, artrite reumatoide, espondilite anquilosante, artrite idiopática juvenil, gota aguda, tendinite, bursite, dor e dismenorreia. Risco de eventos trombóticos cardiovasculares, hemorragia/úlcera GI, lesão renal e hepática — menor dose eficaz, menor duração.',
   'Non-selective NSAID (COX-1/COX-2 inhibition) with a long half-life (allowing twice-daily dosing). Osteoarthritis, rheumatoid arthritis, ankylosing spondylitis, juvenile idiopathic arthritis, acute gout, tendinitis, bursitis, pain and dysmenorrhoea. Risk of cardiovascular thrombotic events, GI bleeding/ulcer, kidney and liver injury — lowest effective dose, shortest duration.',
   E'Alívio dos sintomas da artrose e da artrite reumatoide.\nAlívio dos sintomas da espondilite anquilosante e da artrite idiopática juvenil.\nCrises agudas de gota, tendinites e bursites.\nAlívio da dor (incluindo dor menstrual) e da febre.',
   E'Relief of osteoarthritis and rheumatoid arthritis symptoms.\nRelief of ankylosing spondylitis and juvenile idiopathic arthritis symptoms.\nAcute gout attacks, tendinitis and bursitis.\nRelief of pain (including menstrual pain) and fever.',
   E'Irritação do estômago, azia, náuseas ou dor abdominal.\nHemorragia ou úlcera gastrointestinal — fezes escuras, vómitos com sangue.\nDor de cabeça, tonturas, sonolência ou zumbidos.\nRetenção de líquidos, inchaço, aumento da tensão arterial.\nRisco aumentado de enfarte e AVC, sobretudo em doses altas e uso prolongado.\nProcure ajuda imediata se tiver fezes escuras, vómitos com sangue, dor no peito, falta de ar ou inchaço súbito.',
   E'Stomach irritation, heartburn, nausea or abdominal pain.\nGastrointestinal bleeding or ulcer — dark stools, vomiting blood.\nHeadache, dizziness, drowsiness or tinnitus.\nFluid retention, swelling, raised blood pressure.\nIncreased risk of heart attack and stroke, especially at high doses and with prolonged use.\nSeek immediate help if you have dark stools, vomiting blood, chest pain, shortness of breath or sudden swelling.',
   E'Usar a menor dose eficaz pelo menor tempo possível.\nNão usar após cirurgia cardíaca (CABG) nem no 3.º trimestre de gravidez.\nEvitar combinar com outros AINE, aspirina ou anticoagulantes (risco hemorrágico).\nCautela em idosos e em doentes com doença cardiovascular, renal, hepática ou úlcera prévia.\nTomar com alimentos para reduzir a irritação gástrica.',
   E'Use the lowest effective dose for the shortest time.\nDo not use after heart surgery (CABG) or in the 3rd trimester of pregnancy.\nAvoid combining with other NSAIDs, aspirin or anticoagulants (bleeding risk).\nCaution in older people and in patients with cardiovascular, kidney, liver disease or previous ulcer.\nTake with food to reduce stomach irritation.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Naproxeno: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=24d44eb6-921e-4150-a6b2-81f42ced32ab — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Naproxen label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=24d44eb6-921e-4150-a6b2-81f42ced32ab — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('teofilina',
   'A teofilina é um broncodilatador usado na asma crónica e na DPOC, quando outros tratamentos não são suficientes. Tem uma janela terapêutica estreita — níveis altos causam efeitos graves (vómitos, arritmias, convulsões) e exige análises regulares.',
   'Theophylline is a bronchodilator used in chronic asthma and COPD, when other treatments are not enough. It has a narrow therapeutic window — high levels cause serious effects (vomiting, arrhythmias, seizures) and require regular blood tests.',
   'Metilxantina broncodilatadora (inibição da fosfodiesterase e antagonismo dos recetores da adenosina). Asma crónica e DPOC como terapêutica adicional. Janela terapêutica estreita (10–20 mcg/mL); toxicidade dose-dependente (náuseas, taquicardia, convulsões); muitas interações (inibidores/indutores do CYP1A2 e CYP3A4) — exige monitorização dos níveis séricos.',
   'Bronchodilating methylxanthine (phosphodiesterase inhibition and adenosine receptor antagonism). Chronic asthma and COPD as add-on therapy. Narrow therapeutic window (10–20 mcg/mL); dose-dependent toxicity (nausea, tachycardia, seizures); many interactions (CYP1A2 and CYP3A4 inhibitors/inducers) — requires serum level monitoring.',
   E'Tratamento da asma crónica e da bronquite crónica/DPOC, como terapêutica adicional quando os broncodilatadores habituais não são suficientes.',
   E'Treatment of chronic asthma and chronic bronchitis/COPD, as add-on therapy when usual bronchodilators are not enough.',
   E'Náuseas, vómitos, dor de cabeça ou insónia (efeitos tipo cafeína — sinais precoces de níveis altos).\nTremores, agitação ou irritabilidade.\nPalpitações, batimento cardíaco rápido ou irregular.\nAumento da vontade de urinar (diurese).\nNíveis muito altos: vómitos persistentes, arritmias, convulsões — emergência.\nProcure ajuda imediata se tiver vómitos persistentes, palpitações, convulsões ou confusão.',
   E'Nausea, vomiting, headache or insomnia (caffeine-like effects — early signs of high levels).\nTremors, agitation or irritability.\nPalpitations, fast or irregular heartbeat.\nIncreased urination (diuresis).\nVery high levels: persistent vomiting, arrhythmias, seizures — emergency.\nSeek immediate help if you have persistent vomiting, palpitations, seizures or confusion.',
   E'Análises regulares dos níveis de teofilina no sangue.\nNunca alterar a dose por sua conta — a janela entre eficácia e toxicidade é estreita.\nInformar o médico de toda a medicação — antibióticos, antifúngicos, antiácidos e muitos outros alteram os níveis.\nEvitar o tabaco e alterações bruscas na ingestão de cafeína (afetam os níveis).\nCautela em doentes com úlcera, epilepsia ou arritmias.',
   E'Regular blood tests of theophylline levels.\nNever change the dose on your own — the window between efficacy and toxicity is narrow.\nTell your doctor about all medication — antibiotics, antifungals, antacids and many others change the levels.\nAvoid tobacco and sudden changes in caffeine intake (they affect the levels).\nCaution in patients with ulcers, epilepsy or arrhythmias.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Teofilina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5e64036a-ee3e-42e7-9e59-881f88a4e298 — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Theophylline label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5e64036a-ee3e-42e7-9e59-881f88a4e298 — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('alprazolam',
   'O alprazolam é uma benzodiazepina usada no tratamento de curta duração da ansiedade generalizada e das crises de pânico. É eficaz, mas pode causar dependência, sonolência e comprometer a condução — usar na menor dose e pelo menor tempo possível.',
   'Alprazolam is a benzodiazepine used for short-term treatment of generalised anxiety and panic attacks. It is effective, but can cause dependence, drowsiness and impair driving — use the lowest dose for the shortest time.',
   'Benzodiazepina de ação intermédia (potenciação do GABA-A). Ansiedade generalizada (tratamento agudo) e perturbação de pânico. Dependência e síndrome de privação, sedação e alterações psicomotoras; depressão respiratória (perigo com opioides — contraindicação relativa); metabolizado pelo CYP3A4 — contraindicado com inibidores potentes deste enzima.',
   'Intermediate-acting benzodiazepine (GABA-A potentiation). Generalised anxiety (acute treatment) and panic disorder. Dependence and withdrawal syndrome, sedation and psychomotor impairment; respiratory depression (danger with opioids — relative contraindication); metabolised by CYP3A4 — contraindicated with potent inhibitors of this enzyme.',
   E'Tratamento agudo da perturbação de ansiedade generalizada.\nTratamento da perturbação de pânico, com ou sem agorafobia.\n(Tratamento sintomático de curta duração de ansiedade em situações específicas, por indicação médica.)',
   E'Acute treatment of generalised anxiety disorder.\nTreatment of panic disorder, with or without agoraphobia.\n(Short-term symptomatic treatment of anxiety in specific situations, on medical advice.)',
   E'Sonolência, tonturas, sensação de cabeça leve ou falta de coordenação.\nBoca seca, salivação aumentada ou obstipação.\nAlterações da memória ou da concentração.\nDependência e sintomas de privação (ansiedade, insónia, tremores) se suspender abruptamente.\nRaramente: depressão respiratória (sobretudo com opioides), reações paradoxais.\nProcure ajuda se tiver sonolência excessiva com respiração lenta, confusão ou pensamentos de autoagressão.',
   E'Drowsiness, dizziness, light-headedness or lack of coordination.\nDry mouth, increased salivation or constipation.\nMemory or concentration changes.\nDependence and withdrawal symptoms (anxiety, insomnia, tremors) if stopped abruptly.\nRarely: respiratory depression (especially with opioids), paradoxical reactions.\nSeek help if you have excessive drowsiness with slow breathing, confusion or thoughts of self-harm.',
   E'Usar a menor dose eficaz pelo menor tempo possível (idealmente <4 semanas).\nNão conduzir nem operar máquinas enquanto sentir sonolência.\nNão combinar com álcool, opioides ou outros sedativos — risco de depressão respiratória.\nNão parar abruptamente — a suspensão deve ser gradual, sob orientação médica.\nNão usar com cetoconazol, itraconazol ou outros inibidores potentes do CYP3A4 sem revisão médica.',
   E'Use the lowest effective dose for the shortest time (ideally under 4 weeks).\nDo not drive or operate machinery while feeling drowsy.\nDo not combine with alcohol, opioids or other sedatives — risk of respiratory depression.\nDo not stop abruptly — withdrawal must be gradual, under medical guidance.\nDo not use with ketoconazole, itraconazole or other potent CYP3A4 inhibitors without medical review.',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Alprazolam: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0cf8b567-201b-44fa-8fd3-c74023aff44f — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Alprazolam label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0cf8b567-201b-44fa-8fd3-c74023aff44f — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)'),
  ('adrenalina',
   'A adrenalina (epinefrina) é um medicamento de emergência usado sobretudo no tratamento da anafilaxia (reação alérgica grave) e em situações de paragem cardíaca ou choque. Em caso de anafilaxia, a injeção deve ser feita de imediato — não esperar.',
   'Adrenaline (epinephrine) is an emergency medicine used mainly to treat anaphylaxis (severe allergic reaction) and in cardiac arrest or shock. In anaphylaxis, the injection must be given immediately — do not wait.',
   'Catecolamina endógena (agonista alfa e beta-adrenérgico) — vasoconstrição, inotrópico/cronotrópico positivo e broncodilatação. Primeira linha na anafilaxia (IM no vasto lateral da coxa); hipotensão associada a choque séptico (perfusão IV); paragem cardíaca (ACLS). Vigilância de taquiarritmias, isquemia miocárdica, hipertensão e extravasamento.',
   'Endogenous catecholamine (alpha and beta-adrenergic agonist) — vasoconstriction, positive inotropy/chronotropy and bronchodilation. First line in anaphylaxis (IM into the vastus lateralis of the thigh); hypotension associated with septic shock (IV infusion); cardiac arrest (ACLS). Monitor for tachyarrhythmias, myocardial ischaemia, hypertension and extravasation.',
   E'Tratamento de emergência da anafilaxia (reação alérgica grave): inchaço, dificuldade em respirar, queda da tensão arterial.\nAumento da tensão arterial na hipotensão associada a choque séptico (ambiente hospitalar).\nParagem cardíaca (protocolo de reanimação, por profissionais).\nOutras situações de emergência (broncoespasmo grave, alergias) por indicação médica.',
   E'Emergency treatment of anaphylaxis (severe allergic reaction): swelling, difficulty breathing, drop in blood pressure.\nRaising blood pressure in hypotension associated with septic shock (hospital setting).\nCardiac arrest (resuscitation protocol, by professionals).\nOther emergency situations (severe bronchospasm, allergies) on medical advice.',
   E'Palpitações, batimento cardíaco rápido, tremores ou ansiedade (esperados após a injeção).\nDor de cabeça, tonturas, sudação ou palidez.\nAumento da tensão arterial; em doentes com doença cardíaca: dor no peito, arritmias.\nAumento transitório do açúcar no sangue.\nNecrose local se a injeção for acidental num dedo ou mão.\nProcure ajuda imediata se tiver dor no peito, palpitações fortes, dor de cabeça súbita intensa ou falta de ar.',
   E'Palpitations, fast heartbeat, tremors or anxiety (expected after the injection).\nHeadache, dizziness, sweating or pallor.\nRaised blood pressure; in patients with heart disease: chest pain, arrhythmias.\nTransient rise in blood sugar.\nLocal necrosis if the injection accidentally goes into a finger or hand.\nSeek immediate help if you have chest pain, strong palpitations, sudden severe headache or shortness of breath.',
   E'Em anafilaxia, injetar de imediato no músculo da face externa da coxa — não atrasar; chamar emergência médica depois.\nTer sempre consigo o dispositivo de emergência e verificar a validade.\nApós usar, procurar sempre avaliação médica (a reação pode reaparecer).\nNão injetar num dedo, mão ou pé (risco de necrose).\nCautela em doentes com doença cardíaca, hipertensão, hipertiroidismo ou diabetes (efeitos mais intensos).',
   E'In anaphylaxis, inject immediately into the muscle of the outer thigh — do not delay; call emergency services afterwards.\nAlways carry your emergency device and check the expiry date.\nAfter use, always seek medical evaluation (the reaction may return).\nDo not inject into a finger, hand or foot (risk of necrosis).\nCaution in patients with heart disease, hypertension, hyperthyroidism or diabetes (more intense effects).',
   'DailyMed/FDA (NIH/NLM) — rótulo aprovado Adrenalina (epinefrina): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5726eeca-db88-ba8e-e063-6294a90a927d — com referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)',
   'DailyMed/FDA (NIH/NLM) — approved Adrenaline label (epinephrine): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5726eeca-db88-ba8e-e063-6294a90a927d — with additional reference: Prontuário Terapêutico do INFARMED, INFARMED (11th ed., 2012)')
) AS v(slug, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
       indications_pt, indications_en, side_effects_pt, side_effects_en,
       precautions_pt, precautions_en, source_pt, source_en)
ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;
